def _call_groq_stream(prompt, api_key, model="llama-3.3-70b-versatile"):
    """Stream text chunks from Groq's free-tier OpenAI-compatible API.
    Raises requests.exceptions.RequestException / ValueError on failure."""
    resp = requests.post(
        "https://api.groq.com/openai/v1/chat/completions",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
            "max_tokens": 2000,
        },
        stream=True,
        timeout=120,
    )
    if resp.status_code != 200:
        raise ValueError(f"Groq API error {resp.status_code}: {resp.text[:300]}")
    for line in resp.iter_lines():
        if not line:
            continue
        raw = line.decode("utf-8")
        if not raw.startswith("data: "):
            continue
        payload = raw[len("data: "):]
        if payload.strip() == "[DONE]":
            break
        chunk = json.loads(payload)
        delta = chunk.get("choices", [{}])[0].get("delta", {})
        if delta.get("content"):
            yield delta["content"]

