# ═══════════════════════════════════════════════════════════════════
# ASTRONOMY — Swiss Ephemeris (pyswisseph)
# ═══════════════════════════════════════════════════════════════════
def calc_all_planets(yr, mo, dy, hr, mn, tz_offset, lat, lon):
    """
    Calculate all sidereal planetary positions using Swiss Ephemeris
    (Lahiri ayanamsa).  Returns dict: planet_name → longitude (degrees).
    Also returns lagna longitude.
    """
    # Julian Day in Universal Time
    h_ut  = hr + mn / 60.0 - tz_offset
    jd_ut = swe.julday(yr, mo, dy, h_ut)

    flag  = swe.FLG_SWIEPH | swe.FLG_SIDEREAL

    positions = {}
    for name, pid in _SWE_ID.items():
        ret, _ = swe.calc_ut(jd_ut, pid, flag)
        positions[name] = ret[0] % 360

    # Ketu = Rahu + 180
    positions["கேது"] = (positions["ராகு"] + 180) % 360

    # Lagna (sidereal ascendant) via Swiss Ephemeris houses
    # houses_ex returns sidereal cusps when FLG_SIDEREAL is set via set_sid_mode
    cusps, ascmc = swe.houses_ex(jd_ut, lat, lon, b'P', swe.FLG_SIDEREAL)
    lagna_lon = ascmc[0] % 360          # index 0 = Ascendant

    return jd_ut, positions, lagna_lon

def get_rasi(lon):    return int(lon / 30) % 12
def get_nak(lon):     return int(lon / (360/27)) % 27
def get_pada(lon):    return min(int((lon % (360/27)) / (360/27/4)) + 1, 4)
def get_deg_in_rasi(lon): return lon % 30

def planet_status(planet, rasi):
    if planet in EXALT and EXALT[planet] == rasi:  return "உச்சம் (Exalted)"
    if planet in DEBIL and DEBIL[planet] == rasi:  return "நீச்சம் (Debilitated)"
    if planet in OWN   and rasi in OWN[planet]:    return "சொந்த வீடு (Own)"
    return "சாதாரண (Neutral)"

# ═══════════════════════════════════════════════════════════════════
# DASHA CALCULATIONS
# ═══════════════════════════════════════════════════════════════════
def add_days(dt, days):
    return dt + timedelta(days=round(days))

def calc_vimshottari(birth_dt, mlon):
    ni    = get_nak(mlon)
    lord  = NAK_LORD[ni]
    nak_span = 360/27
    elapsed  = (mlon - ni*nak_span) / nak_span
    remain   = (1 - elapsed) * DASHA_Y[lord]
    si = DASHA_O.index(lord)
    tl = []
    cur = birth_dt
    tl.append({"planet": lord, "start": cur, "end": add_days(cur, remain*365.25), "years": round(remain,2)})
    cur = add_days(cur, remain*365.25)
    for i in range(1, 9):
        p   = DASHA_O[(si+i) % 9]
        yrs = DASHA_Y[p]
        end = add_days(cur, yrs*365.25)
        tl.append({"planet": p, "start": cur, "end": end, "years": yrs})
        cur = end
    today   = datetime.now()
    active  = next((d for d in tl if d["start"] <= today <= d["end"]), tl[0])
    return tl, active

def calc_antardasha(mahadasha_item):
    """Calculate Antardasha (sub-periods) for a given Mahadasha."""
    total_days = (mahadasha_item["end"] - mahadasha_item["start"]).days
    maha_p     = mahadasha_item["planet"]
    maha_yrs   = DASHA_Y[maha_p]
    si = DASHA_O.index(maha_p)
    result = []
    cur = mahadasha_item["start"]
    for i in range(9):
        p    = DASHA_O[(si+i) % 9]
        frac = (DASHA_Y[maha_p] * DASHA_Y[p]) / 120
        days = round(frac * 365.25)
        end  = cur + timedelta(days=days)
        result.append({"planet": p, "start": cur, "end": end, "years": round(frac,2)})
        cur = end
    return result

