# ═══════════════════════════════════════════════════════════════════
# YOGA DETECTION
# ═══════════════════════════════════════════════════════════════════
def detect_yogas(planets, lagna_rasi):
    yogas = []

    sun_r  = get_rasi(planets["சூரியன்"])
    moon_r = get_rasi(planets["சந்திரன்"])
    mars_r = get_rasi(planets["செவ்வாய்"])
    merc_r = get_rasi(planets["புதன்"])
    jup_r  = get_rasi(planets["குரு"])
    ven_r  = get_rasi(planets["சுக்கிரன்"])
    sat_r  = get_rasi(planets["சனி"])
    rahu_r = get_rasi(planets["ராகு"])
    ketu_r = get_rasi(planets["கேது"])

    kendra   = [(lagna_rasi+k)%12 for k in [0,3,6,9]]
    trikona  = [(lagna_rasi+k)%12 for k in [0,4,8]]
    upachaya = [(lagna_rasi+k)%12 for k in [2,5,9,10]]
    dusthana = [(lagna_rasi+k)%12 for k in [5,7,11]]

    # ── 1. Gajakesari Yoga ──────────────────────────────────────────
    diff = (jup_r - moon_r) % 12
    if diff in [0, 3, 6, 9]:
        strength = "🌟🌟🌟🌟🌟" if diff in [0,3] else "🌟🌟🌟🌟"
        yogas.append({"name": "கஜகேசரி யோகம்", "en": "Gajakesari Yoga",
                      "desc": f"சந்திரன் ({RASI[moon_r]}) — குரு ({RASI[jup_r]}) கேந்திரம். புகழ், செல்வம், மக்கள் அன்பு.",
                      "en_desc": f"Moon ({RASI_EN[moon_r]}) – Jupiter ({RASI_EN[jup_r]}) in Kendra. Fame, wealth, intelligence.", "strength": strength})

    # ── 2. Raja Yoga — 9th & 10th lord same or conjunct ────────────
    l9_yg  = RASI_LORD[(lagna_rasi+8)%12]
    l10_yg = RASI_LORD[(lagna_rasi+9)%12]
    if l9_yg == l10_yg:
        yogas.append({"name": "ராஜ யோகம்", "en": "Raja Yoga",
                      "desc": f"9ம் & 10ம் வீட்டு அதிபதி ஒரே கிரகம் — {l9_yg}. அரச மதிப்பு, உயர் அதிகாரம்.",
                      "en_desc": f"Lords of 9th & 10th are same planet ({P_EN[l9_yg]}) — royal status.", "strength": "🌟🌟🌟🌟🌟"})
    elif (l9_yg in planets and l10_yg in planets and
          get_rasi(planets[l9_yg]) == get_rasi(planets[l10_yg])):
        yogas.append({"name": "ராஜ யோகம் (இணைவு)", "en": "Raja Yoga (Conjunction)",
                      "desc": f"9ம் வீட்டு அதிபதி {l9_yg} மற்றும் 10ம் வீட்டு அதிபதி {l10_yg} இணைவு ({RASI[get_rasi(planets[l9_yg])]}). மிகவும் சக்தி வாய்ந்த யோகம்.",
                      "en_desc": f"9th lord {P_EN[l9_yg]} conjunct 10th lord {P_EN[l10_yg]} — powerful Raja Yoga.", "strength": "🌟🌟🌟🌟🌟"})

    # ── 3. Kendra-Trikona Raja Yoga ─────────────────────────────────
    # Lord of trikona (1,5,9) in kendra (1,4,7,10) or vice versa
    trikona_lords = list({RASI_LORD[(lagna_rasi+k)%12] for k in [0,4,8]})
    kendra_lords  = list({RASI_LORD[(lagna_rasi+k)%12] for k in [0,3,6,9]})
    for tl in trikona_lords:
        for kl in kendra_lords:
            if tl != kl and tl in planets and kl in planets:
                tl_r = get_rasi(planets[tl]); kl_r = get_rasi(planets[kl])
                if tl_r == kl_r:  # conjunct
                    yogas.append({"name": f"கேந்திர-த்ரிகோண ராஜ யோகம்",
                                  "en": "Kendra-Trikona Raja Yoga",
                                  "desc": f"திரிகோண அதிபதி {tl} & கேந்திர அதிபதி {kl} இணைவு ({RASI[tl_r]}). அரச சமான வாழ்க்கை, செல்வம்.",
                                  "en_desc": f"Trikona lord {P_EN[tl]} conjunct Kendra lord {P_EN[kl]} — wealth and royal status.",
                                  "strength": "🌟🌟🌟🌟🌟"})
                    break
        else: continue
        break

    # ── 4. Pancha Mahapurusha Yogas ─────────────────────────────────
    if mars_r in kendra and mars_r in [0,7]:
        yogas.append({"name": "ருசக யோகம்", "en": "Ruchaka Yoga (Mars)",
                      "desc": f"செவ்வாய் சொந்த வீடு ({RASI[mars_r]}) + கேந்திரம். தீரம், போர் திறன், நில சொத்து லாபம்.",
                      "en_desc": f"Mars own sign ({RASI_EN[mars_r]}) in Kendra. Courage, military power, property.", "strength": "🌟🌟🌟🌟"})
    if merc_r in kendra and merc_r in [2,5]:
        yogas.append({"name": "பத்ர யோகம்", "en": "Bhadra Yoga (Mercury)",
                      "desc": f"புதன் சொந்த வீடு ({RASI[merc_r]}) + கேந்திரம். அறிவு, வணிக வெற்றி, வாக்கு சக்தி.",
                      "en_desc": f"Mercury own sign ({RASI_EN[merc_r]}) in Kendra. Intelligence, business success.", "strength": "🌟🌟🌟🌟"})
    if jup_r in kendra and jup_r in [8,11]:
        yogas.append({"name": "ஹம்ச யோகம்", "en": "Hamsa Yoga (Jupiter)",
                      "desc": f"குரு சொந்த வீடு ({RASI[jup_r]}) + கேந்திரம். தெய்வீக அருள், ஞானம், அரசு மரியாதை.",
                      "en_desc": f"Jupiter own sign ({RASI_EN[jup_r]}) in Kendra. Divine grace, wisdom.", "strength": "🌟🌟🌟🌟🌟"})
    if ven_r in kendra and ven_r in [1,6]:
        yogas.append({"name": "மாளவ்ய யோகம்", "en": "Malavya Yoga (Venus)",
                      "desc": f"சுக்கிரன் சொந்த வீடு ({RASI[ven_r]}) + கேந்திரம். செல்வம், அழகு, கலை புகழ், சொகுசு வாழ்வு.",
                      "en_desc": f"Venus own sign ({RASI_EN[ven_r]}) in Kendra. Wealth, beauty, artistic fame.", "strength": "🌟🌟🌟🌟"})
    if sat_r in kendra and sat_r in [9,10]:
        yogas.append({"name": "சஸ யோகம்", "en": "Sasa Yoga (Saturn)",
                      "desc": f"சனி சொந்த வீடு ({RASI[sat_r]}) + கேந்திரம். நிலையான உழைப்பு, நீண்ட ஆயுள், அதிகாரம்.",
                      "en_desc": f"Saturn own sign ({RASI_EN[sat_r]}) in Kendra. Lasting authority.", "strength": "🌟🌟🌟🌟"})

    # ── 5. Budha-Aditya Yoga ────────────────────────────────────────
    if sun_r == merc_r:
        h = (sun_r - lagna_rasi) % 12 + 1
        strength = "🌟🌟🌟🌟" if h in [1,4,5,7,9,10] else "🌟🌟🌟"
        yogas.append({"name": "புத-ஆதித்ய யோகம்", "en": "Budha-Aditya Yoga",
                      "desc": f"சூரியன்-புதன் இணைவு ({RASI[sun_r]}, {h}ம் வீடு). அறிவுக்கூர்மை, புகழ், நல்ல தொழில்.",
                      "en_desc": f"Sun-Mercury in {RASI_EN[sun_r]} (House {h}). Sharp intellect, fame, good career.", "strength": strength})

    # ── 6. Chandra-Mangala Yoga ─────────────────────────────────────
    if moon_r == mars_r:
        yogas.append({"name": "சந்திர-மங்கல யோகம்", "en": "Chandra-Mangala Yoga",
                      "desc": f"சந்திரன்-செவ்வாய் இணைவு ({RASI[moon_r]}). செல்வம், வீரம், நில சொத்து மூலம் வருமானம்.",
                      "en_desc": f"Moon-Mars in {RASI_EN[moon_r]}. Wealth through property, courage.", "strength": "🌟🌟🌟"})

    # ── 7. Neecha Bhanga Raja Yoga ──────────────────────────────────
    for dp, debil_r in DEBIL.items():
        if get_rasi(planets.get(dp, 0)) == debil_r:
            dispositor = RASI_LORD[debil_r]
            exalt_r    = EXALT.get(dp, 0)
            exalt_lord = RASI_LORD[exalt_r]
            dp_r = get_rasi(planets.get(dispositor, 0))
            el_r = get_rasi(planets.get(exalt_lord, 0))
            if dp_r in kendra or el_r in kendra or dp_r in trikona:
                yogas.append({
                    "name": f"நீச்ச பங்க ராஜ யோகம் ({P_EN[dp]})",
                    "en":   f"Neecha Bhanga Raja Yoga ({P_EN[dp]})",
                    "desc": f"{dp} நீச்சம் ({RASI[debil_r]}) ஆனால் நீச்ச பங்கம் ஏற்படுகிறது. சவால்களே வெற்றிக்கு படிக்கல் — பலமான யோகம்.",
                    "en_desc": f"{P_EN[dp]} debilitated but cancellation occurs — challenges become stepping stones to great success.",
                    "strength": "🌟🌟🌟🌟"
                })

    # ── 8. Viparita Raja Yoga ───────────────────────────────────────
    d_lords = [RASI_LORD[(lagna_rasi+5)%12], RASI_LORD[(lagna_rasi+7)%12], RASI_LORD[(lagna_rasi+11)%12]]
    d_rasis = {(lagna_rasi+5)%12, (lagna_rasi+7)%12, (lagna_rasi+11)%12}
    vip_in_d = sum(1 for dl in d_lords if dl in planets and get_rasi(planets[dl]) in d_rasis)
    if vip_in_d >= 2:
        yogas.append({
            "name": "விபரீத ராஜ யோகம்",
            "en": "Viparita Raja Yoga",
            "desc": "6, 8, 12ம் வீட்டு அதிபதிகள் துஷ்டான வீடுகளிலேயே — எதிர்பாராத திடீர் உயர்வு, பிரச்னைகளே வெற்றிக்கு வழி.",
            "en_desc": "Lords of 6th/8th/12th in dusthana houses — unexpected rise from adversity.",
            "strength": "🌟🌟🌟🌟"
        })

    # ── 9. Dhana Yoga (Wealth) ──────────────────────────────────────
    l2_yg  = RASI_LORD[(lagna_rasi+1)%12]
    l11_yg = RASI_LORD[(lagna_rasi+10)%12]
    l2r    = get_rasi(planets.get(l2_yg,  0)) if l2_yg  in planets else -1
    l11r   = get_rasi(planets.get(l11_yg, 0)) if l11_yg in planets else -1
    if l2_yg != l11_yg and l2r == l11r and l2r >= 0:
        yogas.append({
            "name": "தன யோகம்",
            "en": "Dhana Yoga",
            "desc": f"2ம் வீட்டு அதிபதி {l2_yg} & 11ம் வீட்டு அதிபதி {l11_yg} இணைவு ({RASI[l2r]}). பெரும் செல்வம் சேர்க்கும் யோகம்.",
            "en_desc": f"2nd lord {P_EN[l2_yg]} conjunct 11th lord {P_EN[l11_yg]} — great wealth accumulation.",
            "strength": "🌟🌟🌟🌟"
        })
    # 2nd lord in 11th or 11th lord in 2nd
    if l2r == (lagna_rasi+10)%12 or l11r == (lagna_rasi+1)%12:
        yogas.append({
            "name": "தன யோகம் (வீட்டு பரிவர்த்தன)",
            "en": "Dhana Yoga (Exchange)",
            "desc": f"2ம் & 11ம் வீட்டு அதிபதிகள் ({l2_yg}, {l11_yg}) பரிவர்த்தன — செல்வம் படிப்படியாக வளரும். நிரந்தர வருமான யோகம்.",
            "en_desc": f"2nd lord {P_EN[l2_yg]} & 11th lord {P_EN[l11_yg]} in exchange — steady wealth growth.",
            "strength": "🌟🌟🌟"
        })

    # ── 10. Adhi Yoga ───────────────────────────────────────────────
    adhi_pos = {(moon_r+5)%12, (moon_r+6)%12, (moon_r+7)%12}
    benefics_adhi = [p for p in ["குரு","சுக்கிரன்","புதன்"] if get_rasi(planets[p]) in adhi_pos]
    if len(benefics_adhi) >= 2:
        yogas.append({
            "name": "ஆதி யோகம்",
            "en": "Adhi Yoga",
            "desc": f"சந்திரனிலிருந்து 6,7,8 இடங்களில் சுப கிரகங்கள்: {', '.join(benefics_adhi)}. அமைச்சர் தர மதிப்பு, சமூக செல்வாக்கு.",
            "en_desc": f"Benefics {', '.join(P_EN[b] for b in benefics_adhi)} in 6/7/8 from Moon — ministerial status and social power.",
            "strength": "🌟🌟🌟🌟🌟"
        })

    # ── 11. Amala Yoga ──────────────────────────────────────────────
    tenth_r = (lagna_rasi+9)%12
    benefics_10 = [p for p in ["குரு","சுக்கிரன்","புதன்"] if get_rasi(planets[p]) == tenth_r]
    if benefics_10:
        yogas.append({
            "name": "அமல யோகம்",
            "en": "Amala Yoga",
            "desc": f"10ம் வீட்டில் சுப கிரகம் ({', '.join(benefics_10)}). தூய்மையான தொழில், நல்ல புகழ், அழியாத கீர்த்தி.",
            "en_desc": f"Benefic {', '.join(P_EN[p] for p in benefics_10)} in 10th — pure fame and spotless career.",
            "strength": "🌟🌟🌟🌟"
        })

    # ── 12. Vasumati Yoga ───────────────────────────────────────────
    upa_set = set(upachaya)
    benefics_upa = [p for p in ["குரு","சுக்கிரன்","புதன்","சந்திரன்"] if get_rasi(planets[p]) in upa_set]
    if len(benefics_upa) >= 3:
        yogas.append({
            "name": "வசுமதி யோகம்",
            "en": "Vasumati Yoga",
            "desc": f"சுப கிரகங்கள் ({', '.join(benefics_upa)}) உபசய வீடுகளில். செல்வம் மற்றும் புகழ் தானே வரும்.",
            "en_desc": f"Benefics ({', '.join(P_EN[p] for p in benefics_upa)}) in upachaya — wealth and fame come naturally.",
            "strength": "🌟🌟🌟🌟"
        })

    # ── 13. Sunapha Yoga ────────────────────────────────────────────
    second_fm = (moon_r+1)%12
    sun_pl = [p for p in ["செவ்வாய்","புதன்","குரு","சுக்கிரன்","சனி"] if get_rasi(planets[p]) == second_fm]
    if sun_pl:
        yogas.append({
            "name": "சுநாஃப யோகம்",
            "en": "Sunapha Yoga",
            "desc": f"சந்திரனுக்கு 2ம் இடத்தில் {', '.join(sun_pl)} ({RASI[second_fm]}). சொந்த முயற்சியால் செல்வம், சமூக மதிப்பு.",
            "en_desc": f"{', '.join(P_EN[p] for p in sun_pl)} in 2nd from Moon — self-made wealth and social standing.",
            "strength": "🌟🌟🌟"
        })

    # ── 14. Anapha Yoga ─────────────────────────────────────────────
    twelfth_fm = (moon_r+11)%12
    ana_pl = [p for p in ["செவ்வாய்","புதன்","குரு","சுக்கிரன்","சனி"] if get_rasi(planets[p]) == twelfth_fm]
    if ana_pl:
        yogas.append({
            "name": "அனாஃப யோகம்",
            "en": "Anapha Yoga",
            "desc": f"சந்திரனுக்கு 12ம் இடத்தில் {', '.join(ana_pl)} ({RASI[twelfth_fm]}). ஆடம்பர வாழ்வு, நல்ல மரியாதை, புகழ்.",
            "en_desc": f"{', '.join(P_EN[p] for p in ana_pl)} in 12th from Moon — dignified comfortable life.",
            "strength": "🌟🌟🌟"
        })

    # ── 15. Durudhura Yoga ──────────────────────────────────────────
    if sun_pl and ana_pl:
        yogas.append({
            "name": "துருத்துர யோகம்",
            "en": "Durudhura Yoga",
            "desc": "சந்திரனுக்கு இரு புறமும் கிரகங்கள் — மிகவும் வசதியான செல்வமான வாழ்க்கை, நல்ல ஆரோக்கியம், மரியாதை.",
            "en_desc": "Planets flanking Moon — prosperous life with wealth, health and lasting respect.",
            "strength": "🌟🌟🌟🌟"
        })

    # ── 16. Kemadruma Yoga (negative) ──────────────────────────────
    neighbors = [(moon_r-1)%12, (moon_r+1)%12]
    other_r = [sun_r, mars_r, merc_r, jup_r, ven_r, sat_r]
    if not any(r in neighbors for r in other_r):
        yogas.append({
            "name": "கேமத்ரும யோகம் ⚠️",
            "en": "Kemadruma Yoga (Challenging)",
            "desc": f"சந்திரன் ({RASI[moon_r]}) இரு புறமும் கிரகமில்லை. சவால்கள் வரலாம். குரு வழிபாடும் விடாமுயற்சியும் வெல்லும்.",
            "en_desc": "No planets adjacent to Moon — life has challenges. Overcome through Jupiter worship and persistence.",
            "strength": "⚠️"
        })

    # ── 17. Shakata Yoga (negative) ─────────────────────────────────
    jup_fm = (jup_r - moon_r) % 12
    if jup_fm in [5,7,11]:
        yogas.append({
            "name": "சகட யோகம் ⚠️",
            "en": "Shakata Yoga (Challenging)",
            "desc": f"குரு சந்திரனிலிருந்து {jup_fm+1}ம் இடத்தில் ({RASI[jup_r]}). வாழ்க்கையில் ஏற்றதாழ்வுகள். விடாமுயற்சியால் வெற்றி.",
            "en_desc": f"Jupiter in {jup_fm+1}th from Moon — ups and downs in life, persist to succeed.",
            "strength": "⚠️"
        })

    # ── 18. Mahabhagya Yoga ─────────────────────────────────────────
    odd_signs = {0,2,4,6,8,10}  # Aries, Gemini, Leo, Libra, Sagittarius, Aquarius
    if sun_r in odd_signs and moon_r in odd_signs and lagna_rasi in odd_signs:
        yogas.append({
            "name": "மஹாபாக்ய யோகம்",
            "en": "Mahabhagya Yoga",
            "desc": f"சூரியன் ({RASI[sun_r]}), சந்திரன் ({RASI[moon_r]}), லக்னம் ({RASI[lagna_rasi]}) மூன்றும் ஒற்றை ராசிகளில். மிகவும் அரிய புண்ணிய யோகம்.",
            "en_desc": "Sun, Moon & Lagna all in odd signs — rare auspicious configuration of great fortune.",
            "strength": "🌟🌟🌟🌟🌟"
        })

    # ── 19. Parvata Yoga ────────────────────────────────────────────
    bene_kendra = [p for p in ["குரு","சுக்கிரன்","புதன்","சந்திரன்"] if get_rasi(planets[p]) in set(kendra)]
    mal_68 = [p for p in ["சூரியன்","செவ்வாய்","சனி","ராகு","கேது"]
              if get_rasi(planets[p]) in {(lagna_rasi+5)%12,(lagna_rasi+7)%12}]
    if len(bene_kendra) >= 2 and not mal_68:
        yogas.append({
            "name": "பர்வத யோகம்",
            "en": "Parvata Yoga",
            "desc": f"சுப கிரகங்கள் ({', '.join(bene_kendra)}) கேந்திரத்தில், 6/8 இல் பாப கிரகங்கள் இல்லை. நிரந்தர செல்வம், புகழ்.",
            "en_desc": f"Benefics in kendras, no malefics in 6/8 — permanent wealth, fame and happiness.",
            "strength": "🌟🌟🌟🌟"
        })

    # ── 20. Chamara Yoga ────────────────────────────────────────────
    ll_yg  = RASI_LORD[lagna_rasi]
    ll_r_y = get_rasi(planets.get(ll_yg, 0)) if ll_yg in planets else -1
    ll_st  = planet_status(ll_yg, ll_r_y) if ll_r_y >= 0 else ""
    if "உச்சம்" in ll_st and ll_r_y in kendra:
        jup_asp = (jup_r - ll_r_y) % 12 + 1
        if jup_asp in [5,7,9]:
            yogas.append({
                "name": "சாமர யோகம்",
                "en": "Chamara Yoga",
                "desc": f"லக்னாதிபதி {ll_yg} உச்சம் ({RASI[ll_r_y]}) + கேந்திரம் + குரு பார்வை. அரச கவுரவம், அழியாத புகழ்.",
                "en_desc": f"Lagna lord {P_EN[ll_yg]} exalted in kendra + Jupiter aspect — royal honors, lasting fame.",
                "strength": "🌟🌟🌟🌟🌟"
            })

    # ── 21. Lakshmi Yoga ────────────────────────────────────────────
    l9_lk = RASI_LORD[(lagna_rasi+8)%12]
    l9r_lk = get_rasi(planets.get(l9_lk, 0)) if l9_lk in planets else -1
    l9_stat = planet_status(l9_lk, l9r_lk) if l9r_lk >= 0 else ""
    if l9r_lk in (set(kendra)|set(trikona)) and "நீச்சம்" not in l9_stat:
        if ven_r in (set(kendra)|set(trikona)):
            yogas.append({
                "name": "லக்ஷ்மி யோகம்",
                "en": "Lakshmi Yoga",
                "desc": f"9ம் வீட்டு அதிபதி {l9_lk} ({RASI[l9r_lk]}) + சுக்கிரன் ({RASI[ven_r]}) இரண்டும் கேந்திர/திரிகோணத்தில். லக்ஷ்மி கடாட்சம், மிகப்பெரிய செல்வம்.",
                "en_desc": f"9th lord {P_EN[l9_lk]} + Venus both in kendra/trikona — Lakshmi's blessing, immense wealth.",
                "strength": "🌟🌟🌟🌟🌟"
            })

    # ── 22. Saraswati Yoga ──────────────────────────────────────────
    if merc_r in (set(kendra)|set(trikona)) and jup_r in (set(kendra)|set(trikona)) and ven_r in (set(kendra)|set(trikona)):
        yogas.append({
            "name": "சரஸ்வதி யோகம்",
            "en": "Saraswati Yoga",
            "desc": f"புதன் ({RASI[merc_r]}), குரு ({RASI[jup_r]}), சுக்கிரன் ({RASI[ven_r]}) மூன்றும் கேந்திர/திரிகோணத்தில். அபரிமிதமான அறிவு, கலை, படைப்பாற்றல்.",
            "en_desc": f"Mercury ({RASI_EN[merc_r]}), Jupiter ({RASI_EN[jup_r]}) & Venus ({RASI_EN[ven_r]}) in kendra/trikona — profound intelligence, creativity.",
            "strength": "🌟🌟🌟🌟🌟"
        })

    # ── 23. Rahu-Jupiter Yoga (Guru-Chandala — warning) ─────────────
    if rahu_r == jup_r:
        yogas.append({
            "name": "குரு-சண்டால யோகம் ⚠️",
            "en": "Guru-Chandala Yoga (Caution)",
            "desc": f"ராகு-குரு இணைவு ({RASI[jup_r]}). ஆன்மீக நம்பிக்கைகளில் குழப்பம் வரலாம். தவறான குருவிடம் செல்லாதீர்கள்.",
            "en_desc": "Rahu-Jupiter conjunction — spiritual confusion, misleading teachers. Stay disciplined.",
            "strength": "⚠️"
        })

    # ── 24. Sun-Moon Opposition (Poornima / full-moon birth) ─────────
    if (sun_r - moon_r) % 12 == 6:
        yogas.append({
            "name": "பூர்ணிமா யோகம்",
            "en": "Full Moon Yoga (Poornima)",
            "desc": f"பூர்ண சந்திரன் ஜனனம் — சூரியன் {RASI[sun_r]}, சந்திரன் {RASI[moon_r]}. மனோ வலிமை, ஆகர்ஷணீய ஆளுமை, மக்கள் புகழ்.",
            "en_desc": "Born at Full Moon — powerful charismatic personality, fame among masses.",
            "strength": "🌟🌟🌟🌟"
        })

