# ═══════════════════════════════════════════════════════════════════
# COMBUSTION CHECK (Astangata)
# ═══════════════════════════════════════════════════════════════════
COMBUST_DEG = {
    "சந்திரன்": 12, "செவ்வாய்": 17, "புதன்": 14,
    "குரு": 11, "சுக்கிரன்": 10, "சனி": 15
}

def check_combustion(planet_lons):
    sun = planet_lons["சூரியன்"]
    result = {}
    for p, thresh in COMBUST_DEG.items():
        diff = abs(planet_lons[p] - sun)
        if diff > 180: diff = 360 - diff
        result[p] = diff <= thresh
    return result

# ═══════════════════════════════════════════════════════════════════
# RETROGRADE CHECK (Vakra)
# ═══════════════════════════════════════════════════════════════════
def check_retrograde(jd_ut):
    flag = swe.FLG_SWIEPH | swe.FLG_SIDEREAL | swe.FLG_SPEED
    retro = {}
    for name, pid in _SWE_ID.items():
        if name == "ராகு": continue
        ret, _ = swe.calc_ut(jd_ut, pid, flag)
        retro[name] = ret[3] < 0
    retro["ராகு"] = True   # Rahu always retrograde
    retro["கேது"] = True   # Ketu always retrograde
    return retro

# ═══════════════════════════════════════════════════════════════════
# PLANETARY ASPECTS — FULL VEDIC DRISHTI
# ═══════════════════════════════════════════════════════════════════
def aspects_from(planet, rasi):
    """All rasi indices aspected by planet sitting in rasi."""
    asp = [(rasi + 6) % 12]                              # universal 7th
    if planet == "செவ்வாய்":
        asp += [(rasi+3)%12, (rasi+7)%12]               # 4th & 8th
    elif planet == "குரு":
        asp += [(rasi+4)%12, (rasi+8)%12]               # 5th & 9th
    elif planet == "சனி":
        asp += [(rasi+2)%12, (rasi+9)%12]               # 3rd & 10th
    return asp

def build_aspect_table(planet_lons):
    """target_rasi → [(planet, aspect_number), ...]"""
    tbl = {i: [] for i in range(12)}
    for p, lon in planet_lons.items():
        r = get_rasi(lon)
        for ar in aspects_from(p, r):
            diff = (ar - r) % 12 + 1
            tbl[ar].append((p, diff))
    return tbl

# ═══════════════════════════════════════════════════════════════════
# GOCHAR — CURRENT TRANSIT POSITIONS
# ═══════════════════════════════════════════════════════════════════
def calc_gochar(dt=None):
    if dt is None: dt = datetime.now()
    jd = swe.julday(dt.year, dt.month, dt.day, dt.hour + dt.minute/60)
    flag = swe.FLG_SWIEPH | swe.FLG_SIDEREAL
    tr = {}
    for name, pid in _SWE_ID.items():
        ret, _ = swe.calc_ut(jd, pid, flag)
        tr[name] = ret[0] % 360
    tr["கேது"] = (tr["ராகு"] + 180) % 360
    return tr

def sade_sati_phase(natal_moon_rasi, transit_sat_rasi):
    diff = (transit_sat_rasi - natal_moon_rasi) % 12
    if diff == 11: return "ஆரம்பம் (Rising Phase)"
    if diff == 0:  return "நடுப்பகுதி (Peak Phase)"
    if diff == 1:  return "விலகுதல் (Setting Phase)"
    return None

