def calc_ashtakavarga(planet_lons, lagna_rasi):
    """
    Returns (individual_av, sarva_av).
    individual_av[planet] = list of 12 bindhu counts (one per sign).
    sarva_av = list of 12 totals (sum of all 7 planets).
    """
    ref = {p: get_rasi(lon) for p, lon in planet_lons.items()}
    ref["lagna"] = lagna_rasi

    individual = {}
    sarva = [0] * 12

    for target, contrib in _AV.items():
        bindhu = [0] * 12
        for ref_key, positions in contrib.items():
            base = ref.get(ref_key)
            if base is None: continue
            for pos in positions:
                bindhu[(base + pos - 1) % 12] += 1
        individual[target] = bindhu
        for i in range(12):
            sarva[i] += bindhu[i]

    return individual, sarva

