# ═══════════════════════════════════════════════════════════════════
_NAT_STR  = {"சூரியன்":7,"சந்திரன்":6,"சுக்கிரன்":5,
              "குரு":4,"செவ்வாய்":3,"சனி":2,"புதன்":1}
_DIG_PEAK = {"சூரியன்":10,"சந்திரன்":4,"செவ்வாய்":10,
              "புதன்":1,"குரு":1,"சுக்கிரன்":4,"சனி":7}

def calc_shadbala(planet_lons, lagna_rasi, jd_ut):
    retro   = check_retrograde(jd_ut)
    combust = check_combustion(planet_lons)
    out = {}
    for p, lon in planet_lons.items():
        if p in ["ராகு","கேது"]:
            out[p] = {"score":5,"label":"நடுத்தரம்","factors":[]}
            continue
        r = get_rasi(lon)
        h = (r - lagna_rasi) % 12 + 1
        sc = 5.0; fac = []

        stat = planet_status(p, r)
        if "உச்சம்"      in stat: sc+=3; fac.append("உச்சம் +3")
        elif "சொந்த வீடு" in stat: sc+=2; fac.append("சொந்த வீடு +2")
        elif "நீச்சம்"   in stat: sc-=3; fac.append("நீச்சம் -3")

        # Directional (Dig Bala)
        peak = _DIG_PEAK.get(p, 1)
        dist = abs(h - peak); dist = min(dist, 12-dist)
        dig = round((6-dist)/6*2, 1); sc+=dig; fac.append(f"திசை +{dig}")

        # Natural (Naisargika)
        nat = round(_NAT_STR.get(p,1)/7*1.5, 1); sc+=nat; fac.append(f"இயல்பு +{nat}")

        if retro.get(p):           sc+=1; fac.append("வக்கிரம் +1")
        if combust.get(p, False):  sc-=2; fac.append("அஸ்தமனம் -2")
        if h in [1,4,5,7,9,10]:   sc+=1; fac.append("கேந்திர/தி +1")
        elif h in [6,8,12]:        sc-=1; fac.append("துஷ்டான -1")

        sc = max(0, min(10, round(sc,1)))
        lbl = ("மிகவும் வலிமை" if sc>=8 else "வலிமை" if sc>=6
               else "சாதாரண" if sc>=4 else "பலவீனம்")
        out[p] = {"score":sc, "label":lbl, "factors":fac}
    return out

# ═══════════════════════════════════════════════════════════════════
# DEEP PERSONALIZED ANALYSIS ENGINE
# ═══════════════════════════════════════════════════════════════════

def deep_analyze(planets, lagna_rasi, dasha_tl, birth_dt, active_dasha, today,
                 aspect_table=None, shadbala=None, sarva_ashtak=None,
                 combust=None, retro=None):
    """
    Generate deep, chart-specific personalized analysis for all life areas.
    Returns a dict with keys: marriage, career, finance, love, wealth, health,
    personality, timeline.
    """

    # ── Shortcuts ──────────────────────────────────────────────────
    def house(p):       # house number (1–12) of a planet
        return (get_rasi(planets[p]) - lagna_rasi) % 12 + 1

    def lord(n):        # ruling planet of house n
        return RASI_LORD[(lagna_rasi + n - 1) % 12]

    def hrasi(n):       # rasi index for house n
        return (lagna_rasi + n - 1) % 12

    def pin(n):         # planets sitting in house n
        r = hrasi(n)
        return [p for p in PLANETS_LIST if get_rasi(planets[p]) == r]

    def pstat(p):
        return planet_status(p, get_rasi(planets[p]))

    def is_benefic(p):
        return p in ["குரு", "சுக்கிரன்", "சந்திரன்", "புதன்"]

    def is_kendra_or_trikona(h_num):
        return h_num in [1, 4, 5, 7, 9, 10]

    def house_strength_label(h_num):
        if h_num in [1, 4, 5, 7, 9, 10]:   return "சாதகமான இடம் (Favourable)"
        if h_num in [2, 3, 11]:             return "நடுத்தர இடம் (Moderate)"
        return "சவாலான இடம் (Challenging)"

    def grade(score):   # score 0–10
        if score >= 8:  return "⭐⭐⭐⭐⭐ மிகவும் சாதகம் (Excellent)"
        if score >= 6:  return "⭐⭐⭐⭐ நல்லது (Good)"
        if score >= 4:  return "⭐⭐⭐ சாதாரண (Average)"
        if score >= 2:  return "⭐⭐ சவால்கள் உண்டு (Challenging)"
        return "⭐ கடினமான காலம் (Difficult)"

    result = {}

    # ─── PERSONALITY / LAGNA ───────────────────────────────────────
    lagna_lord     = lord(1)
    ll_house       = house(lagna_lord)
    ll_stat        = pstat(lagna_lord)
    sun_h          = house("சூரியன்")
    moon_h         = house("சந்திரன்")
    p1             = pin(1)
    lagna_name     = RASI[lagna_rasi]
    lagna_en       = RASI_EN[lagna_rasi]

    pers_score = 5
    if ll_house in [1,4,5,7,9,10]: pers_score += 2
    if "உச்சம்" in ll_stat: pers_score += 2
    if "நீச்சம்" in ll_stat: pers_score -= 2
    if "குரு" in p1 or "சுக்கிரன்" in p1: pers_score += 1
    pers_score = max(0, min(10, pers_score))

    pers_lines = [
        f"உங்கள் லக்னம் **{lagna_name} ({lagna_en})**. "
        + {
            "மேஷம்": "நீங்கள் ஆற்றல் மிக்கவர், முன்னோடி மனப்பான்மை உடையவர். தீர்க்கமான முடிவுகள் எடுக்கும் திறன் உங்களுக்கு இயல்பாகவே அமைந்துள்ளது.",
            "ரிஷபம்": "நீங்கள் நிலைத்தன்மை மிக்கவர், நடைமுறை சிந்தனை உடையவர். செல்வம், அழகு, சொகுசு விரும்புபவர்.",
            "மிதுனம்": "நீங்கள் புத்திசாலி, தகவல் தொடர்பில் வல்லவர். பல்வேறு திறன்கள் உடையவர்.",
            "கடகம்": "நீங்கள் உணர்வாலானவர், குடும்பப் பிரியர். தாய்மை குணங்கள் மிகவும் வலிமையானவை.",
            "சிம்மம்": "நீங்கள் தலைமை குணம் மிக்கவர், கலையில் ஆர்வம் உள்ளவர். புகழுக்கு ஏங்குபவர்.",
            "கன்னி": "நீங்கள் நுணுக்கமான சிந்தனை உடையவர், சேவை மனம் கொண்டவர்.",
            "துலாம்": "நீங்கள் சமநிலை விரும்புபவர், நீதி மனம் கொண்டவர். கூட்டாளி அன்பு மிகவும் முக்கியம்.",
            "விருச்சிகம்": "நீங்கள் ஆழமான சிந்தனை உடையவர், மர்ம இயல்பு கொண்டவர். தீவிர உணர்வுகள் உடையவர்.",
            "தனுசு": "நீங்கள் தாராள மனம் கொண்டவர், தத்துவ சிந்தனை உடையவர். பயணம், ஞானம் விரும்புபவர்.",
            "மகரம்": "நீங்கள் கட்டுப்பாடு மிக்கவர், கடினமாக உழைப்பவர். லட்சியம் உடையவர்.",
            "கும்பம்": "நீங்கள் புதுமை விரும்புபவர், மனித நேயம் மிக்கவர். சுதந்திர சிந்தனை உடையவர்.",
            "மீனம்": "நீங்கள் கனவு மனிதர், ஆன்மீக ஆர்வம் மிக்கவர். கருணை மிகவும் இயல்பானது.",
        }.get(lagna_name, "உங்கள் லக்னம் வலிமையானது.")
    ]
    pers_lines.append(
        f"லக்னாதிபதி **{lagna_lord}** {house_strength_label(ll_house)} ஆகிய "
        f"**{ll_house}ம் வீட்டில்** ({RASI[hrasi(ll_house)]}) நிற்கிறார் — {ll_stat}. "
        + ("இது உங்கள் ஆரோக்கியம், தோற்றம் மற்றும் ஒட்டுமொத்த வாழ்க்கை வலிமைக்கு நல்லது."
           if ll_house in [1,4,5,7,9,10] else
           "இந்த நிலை வாழ்க்கையில் சில சவால்களை தரலாம் — கடினமான உழைப்பால் வெற்றி கிட்டும்.")
    )
    if p1:
        planet_str = "、".join([f"{P_SYM.get(p,'')} {p}" for p in p1])
        pers_lines.append(f"லக்னத்தில் {planet_str} நிற்கிறார்/ள் — இது உங்கள் இயல்பில் நேரடி தாக்கம் செலுத்துகிறது.")

    result["personality"] = {
        "grade": grade(pers_score), "lines": pers_lines, "score": pers_score
    }

    # ─── MARRIAGE ANALYSIS ─────────────────────────────────────────
    l7         = lord(7)
    l7_house   = house(l7)
    venus_h    = house("சுக்கிரன்")
    mars_h     = house("செவ்வாய்")
    jup_h      = house("குரு")
    p7         = pin(7)
    vs         = pstat("சுக்கிரன்")
    manglik    = mars_h in [1, 4, 7, 8, 12]

    marr_score = 5
    if l7_house in [7, 1, 4, 10]:        marr_score += 2
    elif l7_house in [2, 5, 9, 11]:      marr_score += 1
    elif l7_house in [6, 8, 12]:         marr_score -= 2
    if "உச்சம்" in vs:                   marr_score += 2
    if "நீச்சம்" in vs:                  marr_score -= 2
    if "குரு" in p7:                     marr_score += 2
    if "ராகு" in p7 or "சனி" in p7:     marr_score -= 1
    if jup_h in [1, 4, 5, 7, 9, 10]:    marr_score += 1
    if manglik:                           marr_score -= 1
    # Aspect bonus: Jupiter/Venus aspecting 7th house
    if aspect_table:
        asp7 = aspect_table.get(hrasi(7), [])
        if any(p == "குரு" for p,_ in asp7):    marr_score += 1
        if any(p == "சுக்கிரன்" for p,_ in asp7): marr_score += 1
        if any(p == "சனி" for p,_ in asp7):     marr_score -= 1
    # Shadbala: Venus strength directly affects marriage quality
    if shadbala and "சுக்கிரன்" in shadbala:
        vs_sc = shadbala["சுக்கிரன்"]["score"]
        marr_score += round((vs_sc - 5) * 0.3, 0)
    # Ashtakavarga: 7th house bindhu strength
    if sarva_ashtak:
        av7 = sarva_ashtak[hrasi(7)]
        if av7 >= 30: marr_score += 1
        elif av7 <= 20: marr_score -= 1
    marr_score = max(0, min(10, marr_score))

    # ── Marriage timing: scan Mahadasha × Antardasha combinations ──
    # Rule: BOTH maha AND antar planet must activate 7th house zone
    # (7th lord / Venus / Jupiter / 2nd or 11th lord / planet in 7th)
    def _marr_planet(p):
        if p in ["ராகு", "கேது"]:
            # Rahu/Ketu can trigger marriage if they are in 7th house
            return hrasi(7) == get_rasi(planets.get(p, 0))
        ph_ = house(p)
        return (p in ["சுக்கிரன்", "குரு"] or
                ph_ in [7, 2, 11] or
                p == l7)

    marr_windows = []          # (start, end, maha_planet, antar_planet, strength)
    adulthood = birth_dt + timedelta(days=365 * 17)   # skip before age 17

    for d in dasha_tl:
        if d["end"] < adulthood:
            continue
        antars = calc_antardasha(d)
        for a in antars:
            if a["end"] < adulthood:
                continue
            maha_ok  = _marr_planet(d["planet"])
            antar_ok = _marr_planet(a["planet"])
            strength = (2 if maha_ok else 0) + (2 if antar_ok else 0)
            # At least antardasha must be favorable
            if antar_ok and strength >= 2:
                marr_windows.append({
                    "start": a["start"], "end": a["end"],
                    "maha": d["planet"], "antar": a["planet"],
                    "strength": strength
                })
        if len(marr_windows) >= 5:
            break   # stop after finding 5 good windows

    # Sort by strength (strongest first), keep top-3
    marr_windows.sort(key=lambda x: -x["strength"])
    marr_windows = marr_windows[:3]
    marr_windows.sort(key=lambda x: x["start"])    # re-sort by date

    marr_lines = [
        f"7ம் வீட்டு அதிபதி **{l7} ({P_EN[l7]})** {house_strength_label(l7_house)} ஆகிய "
        f"**{l7_house}ம் வீட்டில்** நிற்கிறார். "
        + ("திருமண வாழ்க்கை மிகவும் சுகமாக இருக்கும். துணை நல்ல குணமுடையவராக இருப்பார்."
           if l7_house in [1,4,5,7,9,10] else
           "திருமணத்தில் சில சவால்கள் வரலாம். பொறுமையும் புரிதலும் அவசியம்.")
    ]
    marr_lines.append(
        f"சுக்கிரன் (காதல் கோள்) **{venus_h}ம் வீட்டில்** — {vs}. "
        + {
            "உச்சம் (Exalted)": "துணை மிகவும் அழகாகவும் குணமாகவும் இருப்பார். காதல் திருமணம் சாத்தியம்.",
            "நீச்சம் (Debilitated)": "காதல் விஷயங்களில் கவனம் தேவை. அதிரடி முடிவுகள் வேண்டாம்.",
            "சொந்த வீடு (Own)": "திருமண வாழ்க்கை இனிமையாக இருக்கும். கலை ஆர்வமுள்ள துணை கிடைக்கலாம்.",
        }.get(vs, f"திருமண வாழ்க்கை சாதாரணமாக இருக்கும்.")
    )
    if p7:
        p7_str = ", ".join([f"{P_SYM.get(p,'')} {p}" for p in p7])
        effects = []
        if "குரு" in p7:    effects.append("குரு இருப்பால் திருமணம் மிகவும் புண்ணியமான, ஞானமான கூட்டு ஆகும்.")
        if "சனி" in p7:     effects.append("சனி இருப்பால் திருமணம் சிறிது தாமதமாகலாம், ஆனால் நிலையான உறவு கிடைக்கும்.")
        if "ராகு" in p7:    effects.append("ராகு இருப்பால் வித்தியாசமான சூழலில் திருமணம் நடக்கலாம்.")
        if "செவ்வாய்" in p7: effects.append("செவ்வாய் 7ல் — வலிமையான ஆனால் சற்று வாதிடும் இயல்பு உள்ள துணை.")
        marr_lines.extend(effects)
    if manglik:
        marr_lines.append(f"⚠️ செவ்வாய் {mars_h}ம் வீட்டில் — **மாங்கலிக் (Manglik) தோஷம்** உண்டு. "
                          "மாங்கலிக் துணையை திருமணம் செய்வது சாதகம். விரத வழிபாடு தோஷ நிவர்த்தி செய்யும்.")
    # 7th lord nakshatra gives partner personality clues
    l7_nak  = NAKSHATRA[get_nak(planets[l7])] if l7 not in ["ராகு","கேது"] else "—"
    l7_pada = get_pada(planets[l7]) if l7 not in ["ராகு","கேது"] else "—"
    marr_lines.append(
        f"🌟 7ம் வீட்டு அதிபதி **{l7}** — **{l7_nak}** நட்சத்திரம், பாதம் {l7_pada}. "
        + {
            "அஸ்வினி":"துணை தீர்க்கமான, சுறுசுறுப்பான இயல்பு உடையவராக இருப்பார்.",
            "பரணி":"துணை உறுதியான, பேரழகான குணம் கொண்டவராக இருப்பார்.",
            "கார்த்திகை":"துணை ஆற்றல் மிக்கவர், நேர்மையான குணம் உடையவர்.",
            "ரோகிணி":"துணை இனிமையான, கலை ஆர்வமுள்ள, அன்பான இயல்பு கொண்டவர்.",
            "மிருகசீரிஷம்":"துணை ஆர்வமுள்ள, தேடும் குணம் கொண்ட, புத்திசாலி.",
            "திருவாதிரை":"துணை ஆழமான சிந்தனை, மனோ வலிமை உடையவர்.",
            "புனர்பூசம்":"துணை நம்பகமான, குடும்பப் பிரியர், நிலையான குணம்.",
            "பூசம்":"துணை கருணை மிக்கவர், ஒழுக்கமான, ஞான ஆர்வமுள்ளவர்.",
            "ஆயில்யம்":"துணை உள்ளார்ந்த சிந்தனை உடையவர், தனிச்சிறப்பான இயல்பு.",
            "மகம்":"துணை கம்பீரமான, தலைமை குணம், பாரம்பரிய நேசிப்பவர்.",
            "பூரம்":"துணை கலைஞர் மனோபாவம், சொகுசு விரும்புபவர்.",
            "உத்திரம்":"துணை நம்பகமான, நேர்மையான, கடுமையாக உழைப்பவர்.",
            "ஹஸ்தம்":"துணை திறமையான, நடைமுறை சிந்தனை, சமூக ஈடுபாடு.",
            "சித்திரை":"துணை அழகிய தோற்றம், படைப்பாற்றல், திறமையான கலைஞர்.",
            "சுவாதி":"துணை சுதந்திர சிந்தனையாளர், நடிப்பு அல்லது கலை ஆர்வமுள்ளவர்.",
            "விசாகம்":"துணை லட்சிய நோக்கு மிக்கவர், ஆழமான உணர்வுகள்.",
            "அனுஷம்":"துணை நம்பகமான நண்பர், ஒழுக்கம் மிக்கவர்.",
            "கேட்டை":"துணை தலைமை குணம், வலிமையான மனோபாவம்.",
            "மூலம்":"துணை ஆழமான சிந்தனை, ஆன்மீக ஈடுபாடு.",
            "பூராடம்":"துணை ஆற்றல் மிக்கவர், கலை, தர்க்க சிந்தனை.",
            "உத்திராடம்":"துணை நம்பகமான, நீண்டகால உறவை மதிப்பவர்.",
            "திருவோணம்":"துணை அறிவாளி, தகவல் தொடர்பு சிறப்பு, கலை நேசிப்பவர்.",
            "அவிட்டம்":"துணை துணிச்சலான, புரட்சிகர சிந்தனை உடையவர்.",
            "சதயம்":"துணை சுதந்திர சிந்தனை, அறிவியல்-தொழில்நுட்ப ஆர்வம்.",
            "பூரட்டாதி":"துணை ஆழமான ஆன்மீக ஈடுபாடு, தத்துவ சிந்தனை.",
            "உத்திரட்டாதி":"துணை அமைதியான, ஆழமான உணர்வுகள், கருணை மிக்கவர்.",
            "ரேவதி":"துணை கருணை மிக்கவர், கலை ஆர்வம், மென்மையான இயல்பு.",
        }.get(l7_nak, "துணை நல்ல குணம் உடையவராக இருப்பார்.")
    )
    # 2nd house (family support for marriage)
    l2_m = lord(2); l2_h_m = house(l2_m)
    marr_lines.append(
        f"👨‍👩‍👧 2ம் வீடு (குடும்பம்) அதிபதி **{l2_m}** {l2_h_m}ம் வீட்டில் — "
        + ("குடும்பத்தினர் திருமணத்தில் நல்ல ஆதரவு அளிப்பார்கள். குடும்ப சந்தோஷம் மிகும்."
           if l2_h_m in [1,2,4,5,7,9,10,11] else
           "குடும்பத்தினர் ஆதரவில் சில சவால்கள் வரலாம். பொறுமையாக கையாளவும்.")
    )
    # Venus nakshatra for love quality
    ven_nak = NAKSHATRA[get_nak(planets["சுக்கிரன்"])]
    marr_lines.append(
        f"💕 சுக்கிரன் **{ven_nak}** நட்சத்திரத்தில் — "
        + {
            "அஸ்வினி":"காதல் வாழ்க்கை சுறுசுறுப்பாக, உற்சாகமாக இருக்கும்.",
            "பரணி":"காதல் ஆழமான, ஆசை மிக்க, உறுதியான உணர்வுகளுடன் இருக்கும்.",
            "கார்த்திகை":"காதல் வெளிப்படையான, நேர்மையான பிணைப்பாக இருக்கும்.",
            "ரோகிணி":"காதல் அழகான, கலையான, இன்பமான அனுபவங்களாக இருக்கும்.",
            "மிருகசீரிஷம்":"காதலில் தேடும் மனப்பான்மை — சரியான துணையை நோக்கி நகர்வீர்கள்.",
            "திருவாதிரை":"காதல் ஆழமான, சில நேரம் சவாலான, ஆனால் மாற்றம் தரும்.",
            "புனர்பூசம்":"காதல் வளரும், நம்பிக்கையும் நட்பும் நிறைந்த உறவு.",
            "பூசம்":"காதல் பாதுகாப்பான, ஒழுக்கமான, ஆழமான பிணைப்பு.",
            "ஆயில்யம்":"காதல் சிக்கலான, ஆழமான, மர்ம தன்மை கொண்டது.",
            "மகம்":"காதல் கம்பீரமான, அந்தஸ்த்துடன் கூடிய உயர்ந்த இணைப்பு.",
            "பூரம்":"காதல் சொகுசான, கலைமயமான, இனிமையான அனுபவம்.",
            "உத்திரம்":"காதல் நம்பகமான, நீண்டகாலமான, நிலையான உறவாக வளரும்.",
            "ஹஸ்தம்":"காதல் நடைமுறை சார்ந்த, திறமையான, ஆரோக்கியமான பிணைப்பு.",
            "சித்திரை":"காதல் அழகியல் சார்ந்த, படைப்பாற்றல் நிறைந்த, ஈர்க்கும் உறவு.",
            "சுவாதி":"காதல் சுதந்திரம் தரும், சமன்படுத்தும், நிலையான பிணைப்பு.",
            "விசாகம்":"காதல் லட்சிய நோக்குடன், ஆழமான, உண்மையான உணர்வுகளுடன் இருக்கும்.",
            "அனுஷம்":"காதல் நண்பர் போன்ற, நம்பகமான, நிலையான உறவு.",
            "கேட்டை":"காதல் வலிமையான, தலைமையான, ஆணவம் கலந்த உணர்வு.",
            "மூலம்":"காதல் ஆழமான, ஆன்மீக தொடர்பு, மாற்றம் தரும் உறவு.",
            "பூராடம்":"காதல் ஆர்வமான, ஆற்றல் மிக்க, போட்டி மனோபாவம் கலந்தது.",
            "உத்திராடம்":"காதல் நம்பகமான, நீண்டகால பிணைப்பு, உறுதியான உறவு.",
            "திருவோணம்":"காதல் அறிவு சார்ந்த, தகவல் பரிமாற்றம் நிறைந்த உறவு.",
            "அவிட்டம்":"காதல் புரட்சிகர, சுறுசுறுப்பான, நட்பு கலந்த உறவு.",
            "சதயம்":"காதல் தனித்துவமான, சுதந்திர மனப்பான்மை, அசாதாரண தொடர்பு.",
            "பூரட்டாதி":"காதல் ஆன்மீக தொடர்பு, ஆழமான உணர்வுகள், சில சவால்கள்.",
            "உத்திரட்டாதி":"காதல் கருணை நிறைந்த, அமைதியான, ஆழமான பிணைப்பு.",
            "ரேவதி":"காதல் கருணை மயமான, மென்மையான, ஆன்மீக பிணைப்பு.",
        }.get(ven_nak, "காதல் வாழ்க்கை இனிமையானதாக அமையும்.")
    )
    # Aspect analysis on 7th house
    if aspect_table:
        asp7 = aspect_table.get(hrasi(7), [])
        if asp7:
            asp_str = ", ".join([f"{P_SYM.get(p,'')} {p} ({num}th)" for p,num in asp7])
            marr_lines.append(f"🔭 **7ம் வீட்டை பார்க்கும் கிரகங்கள் (Aspects):** {asp_str}.")
            if any(p == "குரு" for p,_ in asp7):
                marr_lines.append("குரு 7ம் வீட்டை பார்க்கிறார் — திருமண வாழ்க்கை மிகவும் புண்ணியமானது, ஆசீர்வாதம் உண்டு.")
            if any(p == "சனி" for p,_ in asp7):
                marr_lines.append("சனி 7ம் வீட்டை பார்க்கிறார் — திருமணம் தாமதமாகலாம், ஆனால் நிலையான உறவு நிச்சயம்.")
    # Combustion/retrograde of Venus
    if combust and combust.get("சுக்கிரன்"):
        marr_lines.append("⚠️ சுக்கிரன் **அஸ்தமனம் (Combust)** — சூரியனுக்கு அருகில் உள்ளார். காதல் விஷயங்களில் கவனம் தேவை.")
    if retro and retro.get("சுக்கிரன்"):
        marr_lines.append("ℹ️ சுக்கிரன் **வக்கிரம் (Retrograde)** — பழைய காதல் திரும்பலாம். உறவுகளில் யோசனை தேவை.")
    # Ashtakavarga bindhu for 7th house
    if sarva_ashtak:
        av7 = sarva_ashtak[hrasi(7)]
        av_label = "மிகவும் வலிமை (30+)" if av7>=30 else "சாதாரண" if av7>=22 else "பலவீனம் (<22)"
        marr_lines.append(f"📊 **7ம் வீடு அஷ்டகவர்க்க பலம்:** {av7} bindhu — {av_label}.")

    # Display antardasha-level marriage windows
    if marr_windows:
        window_strs = []
        for w in marr_windows:
            ys = w["start"].strftime("%b %Y")
            ye = w["end"].strftime("%b %Y")
            stars = "⭐⭐" if w["strength"] >= 4 else "⭐"
            window_strs.append(
                f"{stars} **{ys} – {ye}** "
                f"({P_EN[w['maha']]} / {P_EN[w['antar']]} Antardasha)"
            )
        marr_lines.append(
            "⏰ **திருமண சாதகமான காலங்கள் (மகா/அந்தர் தசா அடிப்படையில்):**\n" +
            "\n".join(window_strs)
        )
    marr_lines.append(
        "📌 **குறிப்பு:** மேற்கண்ட காலங்கள் தசா/அந்தர் தசா அடிப்படையில் மட்டுமே கணக்கிடப்பட்டுள்ளன. "
        "சரியான திருமண ஆண்டு குரு/சனி கோசார பார்வை (Transit) சேர்த்தே தீர்மானிக்கப்படும். "
        "இது கணினி கணிப்பு மட்டுமே — ஒரு அனுபவமிக்க ஜோதிடர் ஆலோசனை துல்லியமான பலன் தரும்."
    )

    result["marriage"] = {
        "grade": grade(marr_score), "lines": marr_lines, "score": marr_score,
        "windows": marr_windows
    }

    # ─── CAREER & BUSINESS ANALYSIS ────────────────────────────────
    l10       = lord(10)
    l10_house = house(l10)
    sun_h     = house("சூரியன்")
    sat_h     = house("சனி")
    merc_h    = house("புதன்")
    p10       = pin(10)
    l6        = lord(6)
    l6_house  = house(l6)
    sun_stat  = pstat("சூரியன்")
    sat_stat  = pstat("சனி")

    car_score = 5
    if l10_house in [1,4,5,7,9,10]:  car_score += 2
    if "உச்சம்" in sun_stat:          car_score += 1
    if sun_h in [1,4,5,9,10]:         car_score += 1
    if "குரு" in p10 or "சூரியன்" in p10: car_score += 1
    if "ராகு" in p10:                 car_score += 1  # unconventional success
    if "நீச்சம்" in pstat(l10):       car_score -= 2
    if l10_house in [6, 8, 12]:       car_score -= 1
    if aspect_table:
        asp10 = aspect_table.get(hrasi(10), [])
        if any(p == "குரு" for p,_ in asp10):     car_score += 1
        if any(p == "சூரியன்" for p,_ in asp10):  car_score += 1
        if any(p in ["சனி","ராகு"] for p,_ in asp10): car_score -= 1
    if shadbala and l10 in shadbala:
        car_score += round((shadbala[l10]["score"] - 5) * 0.3)
    if sarva_ashtak:
        av10 = sarva_ashtak[hrasi(10)]
        if av10 >= 30: car_score += 1
        elif av10 <= 18: car_score -= 1
    car_score = max(0, min(10, car_score))

    # Business vs Service indicator
    biz_houses = [3, 7, 11]  # 3=initiative, 7=partnership, 11=gains
    svc_houses = [6, 10]     # service/employment
    biz_count = sum(1 for p in ["சூரியன்","புதன்","சுக்கிரன்"] if house(p) in biz_houses)
    svc_count  = sum(1 for p in ["சனி","சூரியன்"] if house(p) in svc_houses)
    career_type = "வணிகம் (Business)" if biz_count >= svc_count else "சேவை/வேலை (Service/Job)"

    car_lines = [
        f"10ம் வீட்டு அதிபதி **{l10} ({P_EN[l10]})** {house_strength_label(l10_house)} ஆகிய "
        f"**{l10_house}ம் வீட்டில்** நிற்கிறார். "
        + ("தொழிலில் உயர்ந்த நிலை கிடைக்கும். புகழும் அங்கீகாரமும் பெருகும்."
           if l10_house in [1,4,5,7,9,10] else
           "தொழிலில் சவால்கள் வரலாம். கடினமான உழைப்பு மட்டுமே வெற்றி தரும்.")
    ]
    car_lines.append(
        f"உங்கள் ஜாதகம் **{career_type}**க்கு சாதகமாக உள்ளது. "
        f"சூரியன் {sun_h}ம் வீட்டில் ({sun_stat}) — "
        + ("அரசு சேவை, நிர்வாக பதவிகள் மிகவும் சாதகம்."
           if sun_h in [1,4,5,9,10] else
           "சொந்த தொழில் அல்லது தனியார் துறை சாதகம்.")
    )
    car_lines.append(
        f"புதன் (வணிக புத்தி) {merc_h}ம் வீட்டில் — "
        + ("IT, தகவல் தொழில்நுட்பம், கணக்கு, ஆலோசனை சேவைகளில் திறமை மிகும்."
           if merc_h in [1,3,5,9,10,11] else
           "கணக்கு, எழுத்து சார்ந்த வேலைகளில் திறமை உண்டு.")
    )
    if p10:
        p10_str = ", ".join([f"{P_SYM.get(p,'')} {p}" for p in p10])
        # Specific planet-in-10th career fields
        p10_fields = []
        if "சூரியன்" in p10:   p10_fields.append("அரசு சேவை, IAS/IPS, அரசியல், மேலாண்மை")
        if "சந்திரன்" in p10:  p10_fields.append("மக்கள் தொடர்பு, நர்சிங், உணவு வணிகம்")
        if "செவ்வாய்" in p10:  p10_fields.append("பொறியியல், ரியல் எஸ்டேட், இராணுவம், விளையாட்டு")
        if "புதன்" in p10:     p10_fields.append("IT, கணக்கு, ஊடகம், கல்வி, சட்டம்")
        if "குரு" in p10:      p10_fields.append("ஆசிரியர், நீதிபதி, மருத்துவர், ஆலோசகர், வெளிநாட்டு சேவை")
        if "சுக்கிரன்" in p10: p10_fields.append("கலை, சினிமா, ஃபேஷன், சுகாதார தொழில், நகை வணிகம்")
        if "சனி" in p10:      p10_fields.append("அரசு வேலை, கட்டுமானம், விவசாயம், நீண்டகால திட்டங்கள்")
        if "ராகு" in p10:     p10_fields.append("AI, தொழில்நுட்பம், வெளிநாடு, அசாதாரண தொழில்")
        if "கேது" in p10:     p10_fields.append("ஆன்மீகம், மருத்துவம், ஆராய்ச்சி, மர்ம விஞ்ஞானம்")
        car_lines.append(
            f"10ம் வீட்டில் {p10_str} நிற்கிறார்/ள். "
            + (f"🎯 **பொருத்தமான தொழில் துறைகள்:** {' / '.join(p10_fields)}." if p10_fields else
               "இது தொழில் வலிமை சிறப்பாக்குகிறது.")
        )
    # Saturn's role in career
    sat_h_c = house("சனி")
    sat_st_c = pstat("சனி")
    car_lines.append(
        f"சனி (தொழில் காரகன்) {sat_h_c}ம் வீட்டில் — {sat_st_c}. "
        + {
            1:"உழைப்பால் மட்டுமே வெற்றி — ஆனால் நிலையான தொழில் வாழ்க்கை கட்டமைக்கும்.",
            4:"வீடு, சொத்து, சிவில் இன்ஜினியரிங், அரசு விவகாரங்களில் வெற்றி.",
            5:"தொழிலில் ஆக்கப்பூர்வமான அணுகுமுறை — தாமதமான ஆனால் நிலையான வெற்றி.",
            7:"கூட்டு வியாபாரம், வெளிநாட்டு தொடர்பு சார்ந்த தொழிலில் சாதகம்.",
            9:"தத்துவம், சட்டம், வெளிநாட்டு சேவை — 40 வயதுக்கு பிறகு பெரிய வெற்றி.",
            10:"தொழிலில் மிகவும் சிறப்பான கட்டம் — கடுமையான உழைப்பால் உயர் நிலை.",
            11:"மூத்தவர்கள் ஆதரவால் வருமானம் — நண்பர் நெட்வொர்க் மிக முக்கியம்.",
        }.get(sat_h_c, "சனியின் தொழில் தாக்கம் மிதமாக உள்ளது. பொறுமையாக உழையுங்கள்.")
    )
    # 6th house (competition, service orientation)
    l6_c = lord(6); l6_h_c = house(l6_c)
    p6_c = pin(6)
    if p6_c:
        car_lines.append(
            f"6ம் வீட்டில் {', '.join(p6_c)} — போட்டிகளை வெல்லும் திறன் அதிகம். "
            "தொழில் இடத்தில் எதிரிகளை எளிதாக கையாளும் திறன் உண்டு."
        )
    # Sun nakshatra for leadership style
    sun_nak_c = NAKSHATRA[get_nak(planets["சூரியன்"])]
    car_lines.append(
        f"☀ சூரியன் (தொழில் அங்கீகாரம்) **{sun_nak_c}** நட்சத்திரத்தில் — "
        + {
            "அஸ்வினி":"தீர்க்கமான முடிவுகள் எடுக்கும் தலைவர்.",
            "கார்த்திகை":"நேரடியான, தீவிரமான தலைமை — நிர்வாகத்தில் சிறப்பு.",
            "ரோகிணி":"கலைஞன் மனோபாவமுள்ள, சுகமான சூழலில் சிறப்பான தொழில் நிர்வாகி.",
            "மிருகசீரிஷம்":"ஆர்வமிக்க, தேடல் மனோபாவமுள்ள தலைவர் — ஆராய்ச்சி சார்ந்த தொழிலில் சிறப்பு.",
            "ஆர்த்ரா":"மாற்றங்களை கையாளும் திறன் — நெருக்கடி நேர தலைமை சிறப்பு.",
            "புனர்பூசம்":"மீளும் திறன் மிக்க, ஊக்கமளிக்கும் தலைவர்.",
            "பூசம்":"பாதுகாக்கும், கவனமான தலைவர் — அரசு, நிர்வாக பதவிகளில் சிறப்பு.",
            "மகம்":"அரச பரம்பரை தலைமை — பெரிய நிறுவன தலைவர்பதவிகளுக்கு பொருத்தமானவர்.",
            "உத்திரம்":"நம்பகமான, நீண்டகால சிந்தனை உடைய தலைவர்.",
            "ஹஸ்தம்":"திறமையான, நடைமுறை முடிவுகள் எடுக்கும் தலைவர்.",
            "சித்திரை":"படைப்பாற்றல் மிக்க, புதுமையான நிர்வாகி.",
            "சுவாதி":"சுதந்திரமான, தன்னிச்சையாக செயல்படும் தலைவர்.",
            "விசாகம்":"லட்சிய நோக்கு மிக்க, இலக்கை நோக்கி நடக்கும் தலைவர்.",
            "அனுஷம்":"நட்பு பூர்வமான, நடைமுறை சிந்தனை உடைய தலைவர்.",
            "கேட்டை":"வலிமையான, மிகவும் தீர்மானமான தலைவர்.",
            "மூலம்":"ஆழமான சிந்தனை, ஆன்மீக தலைமை — தத்துவ, கல்வி துறைகளில் சிறப்பு.",
            "உத்திராடம்":"நீதியான, நம்பகமான தலைவர் — அரசு-நிர்வாக பதவிகளில் மிகச்சிறப்பு.",
            "திருவோணம்":"கற்கும் மனப்பான்மை, ஒழுக்கமான தலைவர் — கல்வி, ஆசிரியர் தொழிலில் சிறப்பு.",
            "அவிட்டம்":"புரட்சிகர, புதுமையான சிந்தனை — தொழில்நுட்பம், நவீன தொழில்களில் சிறப்பு.",
            "சதயம்":"ஆராய்ச்சி மனோபாவம் — விஞ்ஞானம், மருத்துவம், AI துறைகளில் சிறப்பு.",
            "பூரட்டாதி":"ஆழமான புரிதல், ஆன்மீக தலைமை குணம்.",
            "ரேவதி":"கருணை மிக்க, ஊக்கமளிக்கும் தலைவர் — சமூக சேவை, NGO துறைகளில் சிறப்பு.",
        }.get(sun_nak_c, "தலைமை குணம் சிறப்பாக உள்ளது.")
    )

    result["career"] = {
        "grade": grade(car_score), "lines": car_lines, "score": car_score,
        "type": career_type
    }

    # ─── FINANCE & WEALTH ANALYSIS ─────────────────────────────────
    l2        = lord(2)
    l11       = lord(11)
    l2_house  = house(l2)
    l11_house = house(l11)
    jup_stat  = pstat("குரு")
    p2        = pin(2)
    p11       = pin(11)

    fin_score = 5
    if l2_house in [1,2,4,5,7,9,10,11]: fin_score += 1
    if l11_house in [1,2,4,5,7,9,10,11]: fin_score += 1
    if jup_h in [1,2,4,5,7,9,10,11]:    fin_score += 1
    if "உச்சம்" in jup_stat:             fin_score += 2
    if "நீச்சம்" in jup_stat:            fin_score -= 2
    if "சுக்கிரன்" in p2 or "குரு" in p2: fin_score += 1
    if "ராகு" in p2:                     fin_score -= 1
    if l2_house in [6,8,12]:             fin_score -= 1
    if l11_house in [6,8,12]:            fin_score -= 1
    fin_score = max(0, min(10, fin_score))

    fin_lines = [
        f"2ம் வீட்டு அதிபதி (சேமிப்பு) **{l2}** {l2_house}ம் வீட்டில் — "
        + ("செல்வம் சேர்க்கும் திறன் நல்லது. குடும்பச் சொத்துகள் பாதுகாப்பாக இருக்கும்."
           if l2_house in [1,2,4,5,7,9,10,11] else
           "சேமிப்பில் கவனம் தேவை. அவசர செலவுகள் வரலாம்.")
    ]
    fin_lines.append(
        f"11ம் வீட்டு அதிபதி (வருவாய்) **{l11}** {l11_house}ம் வீட்டில் — "
        + ("வருவாய் நல்ல முறையில் வளரும். பலதரப்பட்ட வருமான வழிகள் கிடைக்கும்."
           if l11_house in [1,2,4,5,7,9,10,11] else
           "வருவாயில் ஏற்றதாழ்வுகள் வரலாம். நிலையான சேமிப்பு அவசியம்.")
    )
    fin_lines.append(
        f"குரு (செல்வ கோள்) {jup_h}ம் வீட்டில் — {jup_stat}. "
        + {
            "உச்சம் (Exalted)": "மிகவும் செல்வமான வாழ்க்கை. தங்கம், நகை, சொத்து சேர்க்கும் யோகம் உண்டு.",
            "நீச்சம் (Debilitated)": "பொருளாதார சவால்கள் வரலாம். கடன் விஷயங்களில் கவனம் தேவை.",
            "சொந்த வீடு (Own)": "செல்வம் மெல்ல மெல்ல வளரும். நிலை, வீடு வாங்கல் சாதகம்.",
        }.get(jup_stat, "பொருளாதார வாழ்க்கை சாதாரணமாக இருக்கும். கடினமான உழைப்பால் வளர்ச்சி கிட்டும்.")
    )
    if p2:
        p2_str = ", ".join([f"{P_SYM.get(p,'')} {p}" for p in p2])
        p2_detail = []
        if "குரு" in p2:      p2_detail.append("குரு 2ல் — செல்வம் ஒழுக்கமாக வளரும், நல்ல வாக்கு சக்தி.")
        if "சுக்கிரன்" in p2: p2_detail.append("சுக்கிரன் 2ல் — நகை, ஆடைகள், கலை மூலம் வருமானம்.")
        if "செவ்வாய்" in p2:  p2_detail.append("செவ்வாய் 2ல் — நில, சொத்து மூலம் வருமானம்; செலவில் கவனம்.")
        if "சனி" in p2:       p2_detail.append("சனி 2ல் — செல்வம் மெதுவாக வளரும்; சேமிப்பு முக்கியம்.")
        if "ராகு" in p2:      p2_detail.append("ராகு 2ல் — செலவுகள் கட்டுப்படுத்துங்கள்; கடன் வேண்டாம்.")
        fin_lines.append(f"2ம் வீட்டில் {p2_str}. " + " ".join(p2_detail) if p2_detail
                         else f"2ம் வீட்டில் {p2_str} — செல்வ நிலை சாதகமாக உள்ளது.")
    # AV bindhu for 2nd and 11th house (wealth houses)
    if sarva_ashtak:
        av2  = sarva_ashtak[hrasi(2)]
        av11 = sarva_ashtak[hrasi(11)]
        av_txt = (
            f"📊 **அஷ்டகவர்க்க பலம்:** 2ம் வீடு = **{av2} bindhu**, 11ம் வீடு = **{av11} bindhu**. "
        )
        if av2 >= 28 and av11 >= 28:
            av_txt += "இரண்டும் வலிமையானவை — மிகவும் நல்ல செல்வ யோகம்!"
        elif av2 >= 28:
            av_txt += "2ம் வீடு வலிமையானது — சேமிப்பு திறன் சிறப்பு. 11ம் வீட்டை பலப்படுத்தவும்."
        elif av11 >= 28:
            av_txt += "11ம் வீடு வலிமையானது — வருமான வழிகள் நல்லது. சேமிப்பிலும் கவனம்."
        else:
            av_txt += "இரண்டும் சராசரி — கவனமான திட்டமிடல் மூலம் செல்வம் கட்டமைக்கவும்."
        fin_lines.append(av_txt)
    # Jupiter nakshatra for wealth giving
    jup_nak_f = NAKSHATRA[get_nak(planets["குரு"])]
    fin_lines.append(
        f"💰 குரு (செல்வ காரகன்) **{jup_nak_f}** நட்சத்திரத்தில் — "
        + {
            "புனர்பூசம்":"மீண்டும் மீண்டும் செல்வம் சேர்க்கும் திறன். இழந்தாலும் மீட்டெடுப்பீர்கள்.",
            "விசாகம்":"லட்சியத்தின் மூலம் செல்வம் வரும் — நோக்கத்துடன் முதலீடு செய்யுங்கள்.",
            "பூராடம்":"ஆழமான திட்டமிடல் மூலம் செல்வம் வளரும்.",
            "பூசம்":"ஒழுக்கமான, படிப்படியான செல்வ வளர்ச்சி — நல்ல சேமிப்பு திறன்.",
            "அனுஷம்":"நண்பர்கள், நெட்வொர்க் மூலம் செல்வ வாய்ப்புகள்.",
            "உத்திரட்டாதி":"நம்பகமான, நிலையான, நீண்டகால செல்வ வளர்ச்சி.",
        }.get(jup_nak_f, "குரு கடாட்சம் படிப்படியான செல்வ வளர்ச்சி தரும்.")
    )
    result["finance"] = {
        "grade": grade(fin_score), "lines": fin_lines, "score": fin_score
    }

    # ─── LOVE LIFE ANALYSIS ────────────────────────────────────────
    l5        = lord(5)
    l5_house  = house(l5)
    p5        = pin(5)
    moon_stat = pstat("சந்திரன்")

    love_score = 5
    if l5_house in [1,4,5,7,9,10,11]:  love_score += 2
    if "உச்சம்" in vs:                  love_score += 2
    if "உச்சம்" in moon_stat:           love_score += 1
    if "நீச்சம்" in vs:                 love_score -= 2
