    love_score = max(0, min(10, love_score))

    love_lines = [
        f"5ம் வீட்டு அதிபதி (காதல் வீடு) **{l5}** {house_strength_label(l5_house)} ஆகிய "
        f"**{l5_house}ம் வீட்டில்** நிற்கிறார். "
        + ("காதல் வாழ்க்கை இனிமையாக இருக்கும். நல்ல காதல் அனுபவங்கள் கிட்டும்."
           if l5_house in [1,4,5,7,9,10,11] else
           "காதல் விஷயங்களில் சில தடைகள் வரலாம். பொறுமையும் நம்பிக்கையும் தேவை.")
    ]
    love_lines.append(
        f"சுக்கிரன் {venus_h}ம் வீட்டில் ({vs}) — "
        + ("காதல் உறவுகள் வலிமையாகவும் நீடித்தும் இருக்கும். தாம்பத்திய வாழ்க்கை சுகமானது."
           if venus_h in [1, 4, 5, 7, 9, 11] else
           "உறவுகளில் புரிதல் தேவை. உணர்வு ரீதியான நெருக்கம் முக்கியம்.")
    )
