    if p6:
        p6_str = ", ".join([f"{P_SYM.get(p,'')} {p}" for p in p6])
        hlth_lines.append(f"6ம் வீட்டில் {p6_str} — நோய் நிரோதக சக்தியில் கவனம் தேவை. தொடர்ந்து மருத்துவ பரிசோதனை செய்யவும்.")
