    if rahu_in_p1:
        hlth_lines.append("ராகு லக்னத்தில் — மர்மம் நோய்கள் வரலாம். தொடர்ந்து மருத்துவ பரிசோதனை அவசியம்.")
    # 6th lord (disease potential)
    l6_h_detail = lord(6); l6_h_pos = house(l6_h_detail)
    l6_st = pstat(l6_h_detail) if l6_h_detail not in ["ராகு","கேது"] else ""
