def get_annual_forecast(year, dasha_tl, planets_data, lagna_rasi_idx):
    """Return rich forecast items using 81-combo _MD_AD_THEMES lookup."""
    yr_start = datetime(year, 1, 1)
    yr_end   = datetime(year, 12, 31, 23, 59)
    items, seen = [], set()
    _STAR = {1:"⭐", 2:"⭐⭐", 3:"⭐⭐⭐", 4:"⭐⭐⭐⭐", 5:"⭐⭐⭐⭐⭐"}
    _RATING_LBL = {1:"கடினமான காலம்", 2:"சவாலான காலம்", 3:"கலப்பு பலன்", 4:"நல்ல காலம்", 5:"மிகவும் சாதகம்"}
    _RATING_CLR = {1:"#FF4444", 2:"#FF8844", 3:"#FFB347", 4:"#88FF44", 5:"#44FF88"}
    for d in dasha_tl:
        if d["end"] < yr_start or d["start"] > yr_end:
            continue
        antars = calc_antardasha(d)
        for a in antars:
            if a["end"] < yr_start or a["start"] > yr_end:
                continue
            key = (d["planet"], a["planet"])
            if key in seen:
                continue
            seen.add(key)
            md_p, ad_p = d["planet"], a["planet"]
            t = _MD_AD_THEMES.get((md_p, ad_p),
                    _MD_AD_THEMES.get((md_p, md_p),
                    {"career":"—","finance":"—","relation":"—","health":"—",
                     "spiritual":"குரு வழிபாடு.","rating":3}))
            rating   = t.get("rating", 3)
            overlap_s = max(a["start"], yr_start)
            overlap_e = min(a["end"],   yr_end)
            items.append({
                "md": md_p, "ad": ad_p,
                "start": overlap_s, "end": overlap_e,
                "period_str": f"{overlap_s.strftime('%b')} – {overlap_e.strftime('%b')} {year}",
                "label":    _RATING_LBL[rating],
                "label_clr":_RATING_CLR[rating],
                "stars":    _STAR[rating],
                "rating":   rating,
                "career":   t.get("career",  "—"),
                "finance":  t.get("finance", "—"),
                "relation": t.get("relation","—"),
                "health":   t.get("health",  "—"),
                "spiritual":t.get("spiritual","—"),
                "remedy":   t.get("remedy",  ""),
            })
    return items

