_FAMILY_DB = Path(__file__).parent / "data" / "family_data.json"

RELATION_OPTIONS = [
    "சொந்தம் / Self","தந்தை / Father","தாய் / Mother",
    "மணாளன் / Husband","மனைவி / Wife",
    "மகன் / Son","மகள் / Daughter",
    "சகோதரன் / Brother","சகோதரி / Sister",
    "தாத்தா / Grandfather","பாட்டி / Grandmother",
    "மாமன் / Uncle","அத்தை / Aunt",
    "நண்பன் / Friend","மற்றவர் / Other",
]

def _load_db() -> dict:
    """Load the family database from disk (thread-safe read)."""
    if _FAMILY_DB.exists():
        try:
            with open(_FAMILY_DB, encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError):
            pass
    return {"users": {}}


def _save_db(db: dict) -> None:
    """Persist family database to disk."""
    _FAMILY_DB.parent.mkdir(parents=True, exist_ok=True)
    with open(_FAMILY_DB, "w", encoding="utf-8") as f:
        json.dump(db, f, ensure_ascii=False, indent=2)


def _hash_pw(password: str) -> str:
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


def _register(username: str, password: str, display_name: str = "") -> tuple[bool, str]:
    """Create a new account. Returns (success, message)."""
    db = _load_db()
    uname = username.strip().lower()
    if not uname or len(uname) < 3:
        return False, "பயனர்பெயர் குறைந்தது 3 எழுத்துகள் இருக்கவும் / Min 3 characters"
    if not password or len(password) < 6:
        return False, "கடவுச்சொல் குறைந்தது 6 எழுத்துகள் / Min 6 characters"
    if uname in db["users"]:
        return False, "இந்த பயனர்பெயர் ஏற்கனவே உள்ளது / Username already taken"
    db["users"][uname] = {
        "password_hash": _hash_pw(password),
        "display_name":  display_name.strip() or uname,
        "created":       date.today().isoformat(),
        "members":       [],
    }
    _save_db(db)
    return True, "கணக்கு உருவாக்கப்பட்டது! / Account created!"


def _login(username: str, password: str) -> tuple[bool, str]:
    """Verify credentials. Returns (success, message)."""
    db   = _load_db()
    uname = username.strip().lower()
    user  = db["users"].get(uname)
    if not user:
        return False, "பயனர்பெயர் கிடைக்கவில்லை / Username not found"
    if user["password_hash"] != _hash_pw(password):
        return False, "கடவுச்சொல் தவறானது / Incorrect password"
    return True, user.get("display_name", uname)


def _get_members(username: str) -> list:
    db = _load_db()
    return db["users"].get(username.lower(), {}).get("members", [])


def _add_member(username: str, member: dict) -> None:
    db    = _load_db()
    uname = username.lower()
    member["id"]    = str(uuid.uuid4())
    member["added"] = date.today().isoformat()
    db["users"][uname]["members"].append(member)
    _save_db(db)


def _remove_member(username: str, member_id: str) -> None:
    db    = _load_db()
    uname = username.lower()
    db["users"][uname]["members"] = [
        m for m in db["users"][uname]["members"] if m["id"] != member_id
    ]
    _save_db(db)


def _update_member(username: str, member_id: str, updated: dict) -> None:
    db    = _load_db()
    uname = username.lower()
    members = db["users"][uname]["members"]
    for i, m in enumerate(members):
        if m["id"] == member_id:
            updated["id"]    = member_id
            updated["added"] = m.get("added", date.today().isoformat())
            members[i] = updated
            break
    db["users"][uname]["members"] = members
    _save_db(db)


def _is_admin(username: str) -> bool:
    """Return True if this user has admin privileges."""
    db = _load_db()
    user = db["users"].get(username.lower(), {})
    # First registered user is auto-admin; or explicit flag
    if user.get("is_admin"):
        return True
    # Auto-grant to first user ever created
    all_users = list(db["users"].keys())
    return bool(all_users) and all_users[0] == username.lower()


def _set_admin(username: str, flag: bool) -> None:
    db = _load_db()
    uname = username.lower()
    if uname in db["users"]:
        db["users"][uname]["is_admin"] = flag
        _save_db(db)


def _ban_user(username: str, flag: bool) -> None:
    db = _load_db()
    uname = username.lower()
    if uname in db["users"]:
        db["users"][uname]["banned"] = flag
        _save_db(db)


def _delete_user(username: str) -> None:
    db = _load_db()
    db["users"].pop(username.lower(), None)
    _save_db(db)


def _get_all_users() -> dict:
    return _load_db().get("users", {})


# ── Admin notification store ────────────────────────────────────────
_NOTIF_DB = Path(__file__).parent / "data" / "notifications.json"

def _load_notifs() -> list:
    if _NOTIF_DB.exists():
        try:
            return json.load(open(_NOTIF_DB, encoding="utf-8"))
        except Exception:
            pass
    return []

def _save_notifs(notifs: list) -> None:
    _NOTIF_DB.parent.mkdir(parents=True, exist_ok=True)
    json.dump(notifs, open(_NOTIF_DB, "w", encoding="utf-8"),
              ensure_ascii=False, indent=2)

def _add_notif(title: str, body: str, notif_type: str = "info") -> None:
    notifs = _load_notifs()
    notifs.insert(0, {
        "id":    str(uuid.uuid4()),
        "title": title,
        "body":  body,
        "type":  notif_type,
        "date":  datetime.now().isoformat(),
        "read_by": [],
    })
    _save_notifs(notifs[:100])   # keep last 100

def _mark_notif_read(username: str, notif_id: str) -> None:
    notifs = _load_notifs()
    for n in notifs:
        if n["id"] == notif_id and username not in n["read_by"]:
            n["read_by"].append(username)
    _save_notifs(notifs)

def _unread_count(username: str) -> int:
    return sum(1 for n in _load_notifs() if username not in n.get("read_by", []))


