# ── Divisional chart engine ──────────────────────────────────────────
def calc_divisional(planets: dict, lagna_lon: float, n: int) -> tuple[dict, int]:
    """
    Return (d_positions, d_lagna_rasi) for any D-n chart using the
    standard Parashari multiplication method: d_lon = (lon * n) % 360.
    """
    d_pos = {p: (lon * n) % 360 for p, lon in planets.items()}
    d_lagna = get_rasi((lagna_lon * n) % 360)
    return d_pos, d_lagna


