def calc_d10(planets: dict, lagna_lon: float):
    """Dashamsha (D10) — Career & Profession chart."""
    return calc_divisional(planets, lagna_lon, 10)

def calc_d60(planets: dict, lagna_lon: float):
    """Shastiamsha (D60) — Past karma & soul quality chart."""
    d_pos, d_lagna = calc_divisional(planets, lagna_lon, 60)
    # Each 0.5° = one of 60 divisions; name them
    def shastiamsha_name(lon):
        idx = int((lon % 30) * 2)    # 0-59
        return _D60_MEANING[idx % 60]
    return d_pos, d_lagna, {p: shastiamsha_name(lon) for p, lon in d_pos.items()}


# ── KP Astrology (Krishnamurti Paddhati) ────────────────────────────

_KP_NAK_ORDER = ["கேது","சுக்கிரன்","சூரியன்","சந்திரன்","செவ்வாய்",
                  "ராகு","குரு","சனி","புதன்"]
_KP_DASHA_YEARS = {"கேது":7,"சுக்கிரன்":20,"சூரியன்":6,"சந்திரன்":10,
                    "செவ்வாய்":7,"ராகு":18,"குரு":16,"சனி":19,"புதன்":17}
_KP_TOTAL = 120
_NAK_SPAN = 360 / 27         # 13.3333°

def kp_sublord(lon: float) -> dict:
    """
    Return {nak_lord, sub_lord, sub_sub_lord, nakshatra_idx} for a longitude.
    Uses Krishnamurti Paddhati sub-lord division.
    """
    nak_idx   = int(lon / _NAK_SPAN) % 27
    pos_in_nak = lon % _NAK_SPAN

    # Nakshatra lord follows the cyclic 9-planet order starting from Ashwini(Ketu)
    nak_lord   = _KP_NAK_ORDER[nak_idx % 9]

    # Sub-lord: divide the nakshatra into 9 sub-spans proportional to dasha years
    nak_lord_start_idx = nak_idx % 9
    pos = 0.0
    sub_lord = nak_lord
    for i in range(9):
        p = _KP_NAK_ORDER[(nak_lord_start_idx + i) % 9]
        span = (_KP_DASHA_YEARS[p] / _KP_TOTAL) * _NAK_SPAN
        pos += span
        if pos > pos_in_nak:
            sub_lord = p
            # Sub-sub-lord within sub
            remaining = pos_in_nak - (pos - span)
            sub_pos = 0.0
            for j in range(9):
                sp = _KP_NAK_ORDER[(nak_lord_start_idx + i + j) % 9]
                sub_span = (_KP_DASHA_YEARS[sp] / _KP_TOTAL) * span
                sub_pos += sub_span
                if sub_pos > remaining:
                    return {"nak_lord": nak_lord, "sub_lord": sub_lord,
                            "sub_sub_lord": sp, "nak_idx": nak_idx}
            break
    return {"nak_lord": nak_lord, "sub_lord": sub_lord,
            "sub_sub_lord": sub_lord, "nak_idx": nak_idx}

