def kp_cusp_analysis(jd: float, lat: float, lon: float, tz: float) -> list:
    """
    Calculate KP cuspal sub-lords for all 12 houses.
    Returns list of dicts with house, cusp_lon, nak_lord, sub_lord.
    """
    cusps, ascmc = swe.houses_ex(jd, lat, lon, b'P', swe.FLG_SIDEREAL)
    results = []
    for i, cusp_raw in enumerate(cusps[1:13], start=1):
        cusp_lon = cusp_raw % 360
        kp = kp_sublord(cusp_lon)
        results.append({
            "house":    i,
            "cusp_lon": cusp_lon,
            "rasi":     RASI[get_rasi(cusp_lon)],
            "degree":   f"{cusp_lon % 30:.2f}°",
            "nak_lord": kp["nak_lord"],
            "sub_lord": kp["sub_lord"],
            "sub_sub":  kp["sub_sub_lord"],
            "meaning":  _KP_HOUSE_SIG.get(i, ""),
        })
    return results


