def calc_jaimini_karakas(planets: dict) -> list:
    """
    Calculate Jaimini Chara Karakas (7-planet system).
    Returns list of {planet, karaka_tm, karaka_en, degree, desc}.
    """
    p_list = ["சூரியன்","சந்திரன்","செவ்வாய்","புதன்","குரு","சுக்கிரன்","சனி"]
    p_degs = [(p, planets.get(p, 0) % 30) for p in p_list]
    sorted_p = sorted(p_degs, key=lambda x: x[1], reverse=True)
    result = []
    for i, (p, deg) in enumerate(sorted_p):
        result.append({
            "planet":     p,
            "symbol":     P_SYM.get(p, ""),
            "karaka_tm":  _KARAKA_TM[i],
            "karaka_en":  _KARAKA_EN[i],
            "degree":     f"{deg:.2f}°",
            "desc":       _KARAKA_DESC[i],
        })
    return result

def calc_arudha_lagna(planets: dict, lagna_rasi: int) -> int:
    """Calculate Arudha Lagna (AL) — reflection of lagna."""
    lag_lord = RASI_LORD[lagna_rasi]
    lord_rasi = get_rasi(planets.get(lag_lord, 0))
    dist = (lord_rasi - lagna_rasi) % 12
    al_rasi = (lord_rasi + dist) % 12
    # Correction: if AL falls in 1st or 7th from lagna, move 10 forward
    if al_rasi == lagna_rasi:
        al_rasi = (al_rasi + 9) % 12
    elif al_rasi == (lagna_rasi + 6) % 12:
        al_rasi = (al_rasi + 9) % 12
    return al_rasi


