_TRANSIT_ALERT_DB = Path(__file__).parent / "data" / "transit_cache.json"

def _load_transit_cache() -> dict:
    if _TRANSIT_ALERT_DB.exists():
        try:
            return json.load(open(_TRANSIT_ALERT_DB, encoding="utf-8"))
        except Exception:
            pass
    return {}

def _save_transit_cache(data: dict) -> None:
    _TRANSIT_ALERT_DB.parent.mkdir(parents=True, exist_ok=True)
    json.dump(data, open(_TRANSIT_ALERT_DB, "w", encoding="utf-8"),
              ensure_ascii=False, indent=2)

