def get_transit_alerts(natal_moon_rasi: int, natal_lagna_rasi: int) -> list:
    """
    Compare today's transits with last cached positions.
    Return list of alert dicts: {planet, old_rasi, new_rasi, house_from_moon,
    house_from_lagna, message, color, is_new}.
    """
    today_str = date.today().isoformat()
    cache     = _load_transit_cache()
    alerts    = []

    try:
        today_pos = calc_gochar(datetime.now())
    except Exception:
        return []

    slow_planets = ["சனி","குரு","ராகு","கேது","செவ்வாய்"]

    for p in slow_planets:
        lon = today_pos.get(p, 0)
        cur_rasi = get_rasi(lon)
        old_rasi = cache.get(p)
        _, p_en, p_clr = (_TRANSIT_PLANET_MSG.get(p, ("?","Transit","#FFB347"))[:3]
                          if len(_TRANSIT_PLANET_MSG.get(p, ())) >= 3
                          else ("?", "Transit", "#FFB347"))
        p_en, p_theme, p_clr = _TRANSIT_PLANET_MSG.get(
            p, (P_EN.get(p, p), "Transit", "#FFB347"))
        house_from_moon   = (cur_rasi - natal_moon_rasi) % 12 + 1
        house_from_lagna  = (cur_rasi - natal_lagna_rasi) % 12 + 1
        house_msg         = _HOUSE_TRANSIT_MSG.get(house_from_moon, "")
        invest_good       = (p in _INVEST_GOOD and
                             house_from_moon in _INVEST_GOOD[p])

        is_new = (old_rasi is not None and old_rasi != cur_rasi)
        alerts.append({
            "planet":     p,
            "planet_en":  p_en,
            "theme":      p_theme,
            "color":      p_clr,
            "rasi":       RASI[cur_rasi],
            "rasi_en":    RASI_EN[cur_rasi],
            "old_rasi":   RASI[old_rasi] if old_rasi is not None else None,
            "house_moon": house_from_moon,
            "house_lag":  house_from_lagna,
            "house_msg":  house_msg,
            "invest_good":invest_good,
            "is_new":     is_new,
        })
        cache[p] = cur_rasi

    _save_transit_cache({**cache, "_date": today_str})
    return alerts


