# PANCHANG + NUMEROLOGY + TAROT FUNCTIONS
# ═══════════════════════════════════════════════════════════════════

def calc_panchang(today_dt, lat, lon, tz):
    """Calculate full Panchang for a given date/location."""
    yr, mo, dy = today_dt.year, today_dt.month, today_dt.day
    # JD at 12:00 noon local time (approximate)
    noon_ut = 12.0 - tz
    jd = swe.julday(yr, mo, dy, noon_ut)

    flag = swe.FLG_SWIEPH | swe.FLG_SIDEREAL

    # Sun and Moon positions
    sun_ret, _ = swe.calc_ut(jd, swe.SUN,  flag)
    mon_ret, _ = swe.calc_ut(jd, swe.MOON, flag)
    sun_lon = sun_ret[0] % 360
    mon_lon = mon_ret[0] % 360

    # Vara (weekday)
    weekday = today_dt.weekday()  # 0=Monday in Python
    vara_idx = (weekday + 1) % 7  # 0=Sunday

    # Tithi
    tithi_angle = (mon_lon - sun_lon) % 360
    tithi_idx   = int(tithi_angle / 12)  # 0-29
    tithi_frac  = (tithi_angle % 12) / 12
    paksha      = "சுக்ல பக்ஷம் (வளர்பிறை)" if tithi_idx < 15 else "கிருஷ்ண பக்ஷம் (தேய்பிறை)"

    # Nakshatra (Moon)
    nak_idx  = int(mon_lon / (360/27)) % 27
    nak_frac = (mon_lon % (360/27)) / (360/27)

    # Panchang Yoga
    yoga_lon = (sun_lon + mon_lon) % 360
    yoga_idx = int(yoga_lon / (360/27)) % 27
    yoga_good = yoga_idx in PANCHANG_YOGA_GOOD

    # Karana (half-tithi)
    karana_raw  = int(tithi_angle / 6)
    if karana_raw < 2:
        karana_idx = 7  # Kimstughna (fixed)
    elif karana_raw < 4:
        karana_idx = (karana_raw - 2) + 8
    elif karana_raw >= 58:
        karana_idx = 10
    else:
        karana_idx = (karana_raw - 2) % 7

    # Sunrise / Sunset via Swiss Ephemeris
    try:
        geopos = [lon, lat, 0.0]
        r1, t1 = swe.rise_trans(jd - 1.0, swe.SUN, b'', swe.FLG_SWIEPH,
                                 swe.CALC_RISE, geopos, 1013.25, 15.0)
        r2, t2 = swe.rise_trans(jd - 1.0, swe.SUN, b'', swe.FLG_SWIEPH,
                                 swe.CALC_SET,  geopos, 1013.25, 15.0)
        rise_h = ((t1[0] + 0.5) % 1) * 24 + tz if r1 >= 0 else 6.0
        set_h  = ((t2[0] + 0.5) % 1) * 24 + tz if r2 >= 0 else 18.0
        rise_h %= 24;  set_h %= 24
    except Exception:
        rise_h, set_h = 6.0, 18.0

    day_mins   = (set_h - rise_h) * 60  # minutes of daylight
    slot_mins  = day_mins / 8.0         # each kalam slot

    def kalam_time(slot_num):
        """Return (start_h, end_h) for a 1-based slot."""
        start = rise_h + (slot_num - 1) * slot_mins / 60
        end   = start + slot_mins / 60
        return start, end

    rahu_s, rahu_e   = kalam_time(RAHU_SLOT[vara_idx])
    yama_s,  yama_e  = kalam_time(YAMA_SLOT[vara_idx])
    guli_s,  guli_e  = kalam_time(GULIKAI_SLOT[vara_idx])

    # Abhijit & Brahma Muhurtha
    mid_h     = (rise_h + set_h) / 2
    abhijit_s = mid_h - 24/60
    abhijit_e = mid_h + 24/60
    brahma_s  = rise_h - 96/60
    brahma_e  = rise_h - 48/60

    def fmt_h(h):
        h = h % 24
        return f"{int(h):02d}:{int((h % 1)*60):02d}"

    return {
        "vara_idx": vara_idx,
        "vara":     VARA_TM[vara_idx],
        "vara_en":  VARA_EN[vara_idx],
        "vara_lord":VARA_LORD[vara_idx],
        "tithi_idx":tithi_idx,
        "tithi":    TITHI_TM[tithi_idx],
        "tithi_en": TITHI_EN[tithi_idx],
        "tithi_pct":round(tithi_frac * 100),
        "paksha":   paksha,
        "nak_idx":  nak_idx,
        "nakshatra":NAKSHATRA[nak_idx],
        "nak_en":   NAK_EN[nak_idx],
        "nak_lord": NAK_LORD[nak_idx],
        "nak_pct":  round(nak_frac * 100),
        "yoga_idx": yoga_idx,
        "yoga":     PANCHANG_YOGA_TM[yoga_idx],
        "yoga_good":yoga_good,
        "karana":   KARANA_TM[min(karana_idx, len(KARANA_TM)-1)],
        "sun_lon":  round(sun_lon, 2),
        "mon_lon":  round(mon_lon, 2),
        "sunrise":  fmt_h(rise_h),
        "sunset":   fmt_h(set_h),
        "rahu_kalam":  f"{fmt_h(rahu_s)} – {fmt_h(rahu_e)}",
        "yamagandam":  f"{fmt_h(yama_s)} – {fmt_h(yama_e)}",
        "gulikai":     f"{fmt_h(guli_s)} – {fmt_h(guli_e)}",
        "abhijit":     f"{fmt_h(abhijit_s)} – {fmt_h(abhijit_e)}",
        "brahma":      f"{fmt_h(brahma_s)} – {fmt_h(brahma_e)}",
        "date_str":    today_dt.strftime("%d %B %Y"),
    }


def calc_numerology(full_name, dob):
    """Calculate Life Path, Name Number, and lucky details."""
    # Life Path: reduce DOB digit sum
    digits = [int(c) for c in dob.strftime("%d%m%Y")]
    total  = sum(digits)
    # reduce
    def reduce_num(n):
        if n in (11, 22, 33): return n
        while n > 9:
            n = sum(int(d) for d in str(n))
            if n in (11, 22, 33): break
        return n
    life_path = reduce_num(total)

    # Name Number (Chaldean)
    clean = full_name.lower()
    name_val = sum(CHALDEAN_MAP.get(c, 0) for c in clean if c.isalpha())
    name_num  = reduce_num(name_val)

    # Destiny = life_path (same in most traditions)
    lp_info = LIFE_PATH_MEANINGS.get(life_path, LIFE_PATH_MEANINGS.get(life_path % 9 or 9, {}))
    nn_info = LIFE_PATH_MEANINGS.get(name_num,  LIFE_PATH_MEANINGS.get(name_num  % 9 or 9, {}))

    return {
        "life_path":  life_path,
        "name_num":   name_num,
        "lp_info":    lp_info,
        "nn_info":    nn_info,
        "raw_total":  total,
        "raw_name":   name_val,
    }


def get_daily_tarot(seed_dt):
    """Return a Major Arcana card for the given date (deterministic)."""
    import hashlib
    seed = int(hashlib.md5(seed_dt.strftime("%Y%m%d").encode()).hexdigest(), 16)
    return TAROT_MAJOR[seed % 22]


def daily_horoscope_text(moon_rasi, transit_planets, period="daily"):
    """Generate contextual horoscope text from transit positions."""
    predictions = {"career":"", "love":"", "health":"", "finance":""}
    highlights  = []

    for planet_tm, lon in transit_planets.items():
        transit_rasi = get_rasi(lon)
        house = (transit_rasi - moon_rasi) % 12 + 1
        p_en_map = {"சூரியன்":"sun","சந்திரன்":"moon","குரு":"jupiter",
                    "சனி":"saturn","செவ்வாய்":"mars","சுக்கிரன்":"venus","புதன்":"mercury"}
        p_key = p_en_map.get(planet_tm)
        if not p_key: continue
        effects = _TRANSIT_HOUSE_EFFECT.get(p_key, {}).get(house, {})
        for domain, text in effects.items():
            if domain in predictions and not predictions[domain]:
                predictions[domain] = text
            elif text:
                highlights.append(f"{P_SYM.get(planet_tm,'•')} {text}")

    # Fill blanks with generic
    generic = {
        "career": "தொழிலில் நிலையான முன்னேற்றம் தொடரும்.",
        "love":   "உறவுகளில் அன்பும் புரிதலும் இருக்கும்.",
        "health": "ஆரோக்கியம் சீராக இருக்கும். ஓய்வு முக்கியம்.",
        "finance":"நிதி நிலை சாதாரணமாக இருக்கும். தேவையற்ற செலவை தவிர்க்கவும்.",
    }
    for k in predictions:
        if not predictions[k]:
            predictions[k] = generic[k]

    return predictions, highlights


