def _build_ai_prompt(name, bdate, btime, place, lagna_rasi, moon_rasi,
                     moon_nak, moon_pada, planets, yogas,
                     active_dasha, dasha_tl, reading_type):
    """Build detailed Vedic chart context prompt for Claude AI."""
    today = datetime.now()

    pos_y = [y for y in yogas if "⚠️" not in y.get("strength", "")]
    neg_y = [y for y in yogas if "⚠️" in y.get("strength", "")]

    planet_lines = []
    for p in PLANETS_LIST:
        lon = planets.get(p, 0)
        r   = get_rasi(lon)
        deg = lon % 30
        st_  = planet_status(p, r) if p not in ("ராகு", "கேது") else "—"
        planet_lines.append(
            f"  - {P_EN[p]}: {RASI_EN[r]} ({deg:.1f}°) [house "
            f"{((r - lagna_rasi) % 12) + 1}] [{st_}]"
        )

    upcoming = [d for d in dasha_tl if d["end"] > today][:5]
    dasha_lines = []
    for d in upcoming:
        marker = "  ◀ ACTIVE NOW" if d is active_dasha else ""
        dasha_lines.append(
            f"  - {P_EN[d['planet']]} Mahadasha: "
            f"{d['start'].strftime('%Y')}–{d['end'].strftime('%Y')}{marker}"
        )

    focus_map = {
        "பொதுவான ஜாதக வாசிப்பு": (
            "Provide a comprehensive birth chart reading: personality profile, "
            "life purpose, major strengths and challenges, and the most important "
            "themes for this person's life."
        ),
        "தொழில் & செல்வம்": (
            "Focus on career potential, professional path, financial prospects, "
            "wealth-building strategies, and business opportunities based on the "
            "10th, 2nd, and 11th houses and their lords."
        ),
        "உறவுகள் & திருமணம்": (
            "Focus on relationships, marriage timing, compatibility needs, "
            "emotional patterns, and family life based on the 7th, 5th, and 4th houses."
        ),
        "ஆரோக்கியம்": (
            "Focus on health tendencies, body constitution, potential areas of "
            "vulnerability, and wellness practices suited to this chart."
        ),
        "ஆன்மீகம் & தர்மம்": (
            "Focus on dharma, spiritual path, karma patterns, life purpose, "
            "and spiritual practices that would most benefit this person."
        ),
        "நடப்பு தசா விவரம்": (
            f"Focus entirely on the current {P_EN[active_dasha['planet']]} Mahadasha "
            f"(active until {active_dasha['end'].strftime('%B %Y')}): its core themes, "
            "what is unfolding right now, the next 2–3 year outlook, and how to "
            "make the most of this period."
        ),
    }
    # match by prefix so dropdown text (with Tamil) still finds the key
    focus = next(
        (v for k, v in focus_map.items() if reading_type.startswith(k)),
        focus_map["பொதுவான ஜாதக வாசிப்பு"]
    )

    prompt = f"""You are a deeply knowledgeable Vedic astrologer, expert in Tamil Jyotish tradition.
Provide a personalised, insightful birth-chart reading for the person below.

════════════════════════════════════
BIRTH DETAILS
════════════════════════════════════
Name  : {name}
Date  : {bdate.strftime('%d %B %Y')}
Time  : {btime.strftime('%H:%M')} IST
Place : {place or 'India'}

════════════════════════════════════
SIDEREAL CHART (Lahiri Ayanamsa)
════════════════════════════════════
Lagna (Ascendant) : {RASI_EN[lagna_rasi]} ({RASI[lagna_rasi]})
Moon Sign (Rasi)  : {RASI_EN[moon_rasi]}  ({RASI[moon_rasi]})
Birth Nakshatra   : {NAK_EN[moon_nak]} ({NAKSHATRA[moon_nak]}), Pada {moon_pada}

Planetary Positions (sign, degree, house from lagna, dignity):
{chr(10).join(planet_lines)}

════════════════════════════════════
YOGAS (Planetary Combinations)
════════════════════════════════════
Positive yogas ({len(pos_y)}): {', '.join(y['name'] for y in pos_y[:8]) or 'None'}
Challenging yogas ({len(neg_y)}): {', '.join(y['name'] for y in neg_y[:4]) or 'None'}

════════════════════════════════════
VIMSHOTTARI DASHA TIMELINE
════════════════════════════════════
{chr(10).join(dasha_lines)}

════════════════════════════════════
READING FOCUS
════════════════════════════════════
{focus}

════════════════════════════════════
RELIABILITY RULES — READ CAREFULLY
════════════════════════════════════
- Every claim must be traceable to a specific fact given above (a planet's sign/house/
  dignity, a named yoga, or the active Dasha/Antardasha). Do NOT state generic
  "Barnum" astrology lines that would apply to anyone (e.g. "you are hardworking but
  sometimes doubt yourself") unless you tie it explicitly to a placement.
- When two factors conflict (e.g. a benefic yoga but a debilitated house lord), say so
  explicitly and explain how they balance out — don't smooth over the tension.
- Distinguish clearly between (a) what the chart geometry indicates structurally
  (birth-permanent, high confidence) and (b) what is time-bound and tied to the current
  Dasha/Antardasha (changes over the years) and (c) general remedial suggestions
  (traditional practice, not a guarantee). Label which is which.
- If the data given is insufficient to say something with confidence (e.g. exact
  marriage timing without a divisional chart), say plainly that finer timing would need
  a Navamsa/divisional chart and a trained astrologer, rather than inventing precision.

WRITING INSTRUCTIONS
════════════════════════════════════
1. Structure the reading with clear markdown headers (##) so it's easy to scan:
   ## Personality Snapshot, then 2-4 headers matching the reading focus below,
   ## Current Dasha — What's Unfolding Now, ## Key Yogas & What They Mean,
   and ## Practical Next Steps.
2. Personality Snapshot: 3-4 sentences grounded in Lagna + Moon + their house lords.
3. Address the reading focus in real depth — for each relevant house, name the house,
   its significations, its lord's placement/dignity, and what that combination implies.
   Don't just assert an outcome; briefly show the reasoning (e.g. "10th lord X sits in
   house Y with Z dignity, which typically supports...").
4. Current Dasha section: explain the active Mahadasha's core themes, roughly where in
   the period the person is now, and what the next 1-3 years look like. Mention the next
   upcoming Dasha briefly too.
5. Yogas section: explain 2-4 key yogas by name (both positive and challenging if any
   exist) and their real-world effects for this specific person — not a dictionary
   definition of the yoga.
6. Practical Next Steps: 4-6 concrete, actionable suggestions (timing windows, what to
   focus energy on, what to double-check with a professional astrologer, remedies if
   traditionally associated with a challenging factor mentioned above).
7. Write in clear English; use Tamil astrological terms with an inline translation the
   first time each appears.
8. Tone: warm, specific, realistic — neither vague flattery nor fear-based prediction.
9. Length: 900-1300 words — enough room to actually show the reasoning, not just the
   conclusion.
10. End with one short line noting this is a computed reading meant as guidance, and that
    a qualified astrologer should be consulted for major life decisions.
"""
    return prompt


# ═══════════════════════════════════════════════════════════════════
# MAIN APP
# ═══════════════════════════════════════════════════════════════════
def _build_porutham_report(p1_name, p1_bdate, p1_btime, p1_place, p1_rasi_name, p1_nak_name,
                            p2_name, p2_bdate, p2_btime, p2_place, p2_rasi_name, p2_nak_name,
                            ashta_result, mangal_p1, mangal_p2, doshas, verdict, kt):
    """Plain-text porutham report combining Ashta Kuta + Mangal Dosha + Kattam/Thisai."""
    L = []
    L.append("═" * 64)
    L.append(f"  திருமண பொருத்தம் (MARRIAGE POROTHAM) — {p1_name} & {p2_name}")
    L.append("═" * 64)
    L.append("")
    L.append(f"  {p1_name}")
    L.append(f"    பிறந்த தேதி/நேரம் : {p1_bdate.strftime('%d-%m-%Y')}  {p1_btime.strftime('%I:%M %p')}")
    L.append(f"    பிறந்த இடம்       : {p1_place or '—'}")
    L.append(f"    ராசி / நட்சத்திரம்: {p1_rasi_name} / {p1_nak_name}")
    L.append(f"    செவ்வாய் தோஷம்    : {'உண்டு' if mangal_p1['has_dosha'] else 'இல்லை'}")
    L.append("")
    L.append(f"  {p2_name}")
    L.append(f"    பிறந்த தேதி/நேரம் : {p2_bdate.strftime('%d-%m-%Y')}  {p2_btime.strftime('%I:%M %p')}")
    L.append(f"    பிறந்த இடம்       : {p2_place or '—'}")
    L.append(f"    ராசி / நட்சத்திரம்: {p2_rasi_name} / {p2_nak_name}")
    L.append(f"    செவ்வாய் தோஷம்    : {'உண்டு' if mangal_p2['has_dosha'] else 'இல்லை'}")
    L.append("")
    L.append("─" * 64)
    L.append(f"  அஷ்ட கூட பொருத்தம் (ASHTA KUTA) — {ashta_result['total']}/{ashta_result['max']}")
    L.append("─" * 64)
    for kname, kdata in ashta_result["details"].items():
        mark = "✅" if kdata["ok"] else "⚠️"
        L.append(f"  {mark} {kname:<20} {kdata['score']}/{kdata['max']}  — {kdata['detail']}")
    L.append("")
    L.append(f"  இறுதி தீர்ப்பு: {verdict}")
    if doshas:
        L.append(f"  குறைபாடுகள்: {', '.join(doshas)}")
    L.append("")
    L.append("─" * 64)
    L.append(f"  கட்டம் + திசை பொருத்தம் — {kt['overall_score']}/10  {kt['overall_stars']}")
    L.append("─" * 64)
    for tname, tdata in kt["topics"].items():
        L.append(f"  {tname}: {tdata['score']}/10 {tdata['stars']}")
        L.append(f"      {tdata['text']}")
    if kt["challenges"]:
        L.append("")
        L.append("  ⚠️ முக்கியமான challenges:")
        for c in kt["challenges"]:
            L.append(f"    - {c}")
    L.append("")
    L.append("═" * 64)
    L.append("  இது ஒரு preliminary கணிப்பு. இறுதி முடிவுக்கு முன் ஜோதிடரிடம் ஆலோசிக்கவும்.")
    L.append("═" * 64)
    return "\n".join(L)

def main():
    # ════════════════════════════════════════════════════════════════
    # GLOBAL LOGIN GATE — show login screen if not authenticated
    # ════════════════════════════════════════════════════════════════
    if not st.session_state.get("fp_logged_in"):
        _render_global_login()
        return

    username     = st.session_state["fp_username"]
    display_name = st.session_state.get("fp_display_name", username)
    members      = _get_members(username)
    is_admin_user = _is_admin(username)

    # ── Sidebar ──────────────────────────────────────────────────────
    with st.sidebar:
        # ── Header: app name + logged-in user + logout ───────────────
        st.markdown("## 🌟 ஜாதகம் Pro")
        st.markdown(
            f"<div style='background:#0a1f0a;border:1px solid #44FF88;border-radius:8px;"
            f"padding:7px 10px;margin-bottom:6px;display:flex;justify-content:space-between;"
            f"align-items:center'>"
            f"<span style='color:#44FF88;font-size:0.88rem'>👤 <b>{display_name}</b></span>"
            f"<span style='color:#888;font-size:0.78rem'>@{username}</span></div>",
            unsafe_allow_html=True)
        if st.button("🚪 வெளியேறு / Logout", key="main_logout", use_container_width=True):
            for k in list(st.session_state.keys()):
                st.session_state.pop(k, None)
            st.rerun()
        st.divider()

        # ── Person Selector ──────────────────────────────────────────
        st.markdown("### 👤 நபர் தேர்ந்தெடு / Select Person")
        _CUSTOM = "✏️  Custom / புதிய நபர்"
        _MANAGE = "⚙️  குடும்பம் நிர்வகி / Manage Family"
        person_labels = [
            f"{'🌟 ' if 'சொந்தம்' in m.get('relation','') or 'Self' in m.get('relation','') else '👤 '}"
            f"{m['name']}  ·  {m.get('relation','').split('/')[0].strip()}"
            for m in members
        ]
        all_opts = [_CUSTOM] + person_labels + [_MANAGE]

        # preserve selection across reruns
        prev_idx = st.session_state.get("_sel_person_idx", 0)
        sel_idx = st.radio(
            "person_radio", range(len(all_opts)),
            format_func=lambda i: all_opts[i],
            index=min(prev_idx, len(all_opts)-1),
            key="active_person_idx",
            label_visibility="collapsed",
        )
        st.session_state["_sel_person_idx"] = sel_idx
        st.divider()

        # ── Section Navigation ───────────────────────────────────────
        _nav_opts = ["🔥 இன்று", "🌟 ஜாதகம்", "📅 பஞ்சாங்கம்",
                     "🔮 ராசி கணிப்பு", "🔢 எண் கணிதம்",
                     "🃏 Tarot", "🔔 நினைவூட்டல்", "📸 Image AI"]
        if is_admin_user:
            _nav_opts.append("🛠️ Admin Panel")
        # Show unread notification badge
        _unread = _unread_count(username)
        if _unread:
            _nav_opts_display = [
                f"{o} 🔴 {_unread}" if o == "🔔 நினைவூட்டல்" else o
                for o in _nav_opts
            ]
        else:
            _nav_opts_display = _nav_opts
        nav_section = st.radio(
            "📍 பகுதி / Section",
            _nav_opts_display,
            label_visibility="visible",
        )
        st.divider()

        # ── Birth data: either custom form or auto-filled from member ─
        _city_coords = {
            "Chennai (13.08°N, 80.27°E)":   (13.08, 80.27),
            "Mumbai (19.07°N, 72.87°E)":    (19.07, 72.87),
            "Delhi (28.61°N, 77.20°E)":     (28.61, 77.20),
            "Bengaluru (12.97°N, 77.59°E)": (12.97, 77.59),
            "Kolkata (22.57°N, 88.36°E)":   (22.57, 88.36),
            "Coimbatore (11.01°N, 76.96°E)":(11.01, 76.96),
            "Madurai (9.93°N, 78.12°E)":    (9.93,  78.12),
            "Trichy (10.79°N, 78.70°E)":    (10.79, 78.70),
        }

        gen = False
        panchang_date = horoscope_period = tarot_date = None   # defaults

        is_custom  = (sel_idx == 0)
        is_manage  = (sel_idx == len(all_opts) - 1)
        is_member  = not is_custom and not is_manage

        if is_custom:
            # ── Custom Person form ────────────────────────────────
            st.markdown("### 📋 பிறப்பு விவரங்கள்")
            name  = st.text_input("பெயர் / Name", value="", placeholder="உங்கள் பெயர்", key="c_name")
            bdate = st.date_input("பிறந்த தேதி", value=date(1990,8,15),
                                   min_value=date(1900,1,1), max_value=date(2025,12,31), key="c_bdate")
            btime = st.time_input("பிறந்த நேரம்", value=datetime(2000,1,1,6,30).time(), key="c_btime")
            place = st.text_input("பிறந்த இடம்", placeholder="Chennai", key="c_place")
            tz    = st.slider("Time Zone (UTC+)", -12.0, 14.0, 5.5, 0.5, key="c_tz")
            city_preset = st.selectbox("நகரம்", ["Manual Entry"] + list(_city_coords.keys()), key="c_city")
            def_lat, def_lon = _city_coords.get(city_preset, (13.08, 80.27))
            lat_deg = st.number_input("Latitude °N",  -90.0, 90.0,  def_lat, 0.01, format="%.4f", key="c_lat")
            lon_deg = st.number_input("Longitude °E", -180.0, 180.0, def_lon, 0.01, format="%.4f", key="c_lon")
            st.divider()
            _nk = nav_section.split(" 🔴")[0].strip()
            if _nk == "🌟 ஜாதகம்":
                gen = st.button("✨ ஜாதகம் உருவாக்கு", use_container_width=True, type="primary")
            elif _nk == "📅 பஞ்சாங்கம்":
                panchang_date = st.date_input("Panchang Date", value=date.today(), key="p_date")
            elif _nk == "🔮 ராசி கணிப்பு":
                horoscope_period = st.radio("காலம்", ["இன்று","இந்த வாரம்","இந்த மாதம்","இந்த ஆண்டு"], key="h_period")
                if not st.session_state.get("jadhagam_generated"):
                    gen = st.button("✨ ஜாதகம் உருவாக்கு", use_container_width=True, key="gen2")
            elif _nk == "🃏 Tarot":
                tarot_date = st.date_input("Tarot Date", value=date.today(), key="t_date")

        elif is_member:
            # ── Auto-fill from stored family member ───────────────
            m = members[sel_idx - 1]
            name = m["name"]
            try:
                bdate = date.fromisoformat(m["birth_date"])
                _h, _mn = map(int, m.get("birth_time","06:00").split(":"))
                btime = datetime(2000,1,1,_h,_mn).time()
            except Exception:
                bdate = date(1990,1,1)
                btime = datetime(2000,1,1,6,0).time()
            place   = m.get("place","")
            tz      = float(m.get("tz", 5.5))
            lat_deg = float(m.get("lat", 13.08))
            lon_deg = float(m.get("lon", 80.27))
            # Family member → auto-generate chart
            st.session_state["jadhagam_generated"] = True

            # Compact member info card
            rel_clr = ("#44FF88" if "சொந்தம்" in m.get("relation","") or "Self" in m.get("relation","")
                       else "#FFB347")
            st.markdown(
                f"<div style='background:#1e0a3c;border:2px solid {rel_clr};"
                f"border-radius:10px;padding:10px;margin-bottom:8px'>"
                f"<div style='color:{rel_clr};font-weight:700;font-size:1.0rem'>{name}</div>"
                f"<div style='color:#aaa;font-size:0.8rem'>{m.get('relation','')}</div>"
                f"<div style='color:#888;font-size:0.78rem;margin-top:6px'>"
                f"📅 {m.get('birth_date','')} &nbsp; {m.get('birth_time','')}<br>"
                f"📍 {m.get('place','')} &nbsp; UTC+{tz}<br>"
                f"🌐 {lat_deg:.2f}°N  {lon_deg:.2f}°E</div></div>",
                unsafe_allow_html=True)

            _nk2 = nav_section.split(" 🔴")[0].strip()
            if _nk2 == "📅 பஞ்சாங்கம்":
                panchang_date = st.date_input("Panchang Date", value=date.today(), key="p_date")
            elif _nk2 == "🔮 ராசி கணிப்பு":
                horoscope_period = st.radio("காலம்", ["இன்று","இந்த வாரம்","இந்த மாதம்","இந்த ஆண்டு"], key="h_period")
            elif _nk2 == "🃏 Tarot":
                tarot_date = st.date_input("Tarot Date", value=date.today(), key="t_date")

        else:  # is_manage
            # Dummy values — manage section doesn't need birth data
            name = display_name; bdate = date(1990,1,1)
            btime = datetime(2000,1,1,6,0).time()
            place = ""; tz = 5.5; lat_deg = 13.08; lon_deg = 80.27

        st.caption("⚙️ Powered by Vedic Astrology\nLahiri Ayanamsa · Vimshottari Dasha")

    # ── Persist custom generated state ──────────────────────────────
    if gen:
        st.session_state["jadhagam_generated"] = True

    # Normalise nav_section — strip badge suffix added for unread count
    _nav_key = nav_section.split(" 🔴")[0].strip()

    # ════════════════════════════════════════════════════════════════
    # ROUTE BY SECTION  (or Family Manage mode)
    # ════════════════════════════════════════════════════════════════

    # ── Manage Family (from person selector) ─────────────────────────
    if is_manage:
        _render_family_portal(username, display_name, members)
        return

    # ── 🛠️ ADMIN PANEL ────────────────────────────────────────────────
    if _nav_key == "🛠️ Admin Panel":
        if is_admin_user:
            _render_admin_panel(username)
        else:
            st.error("⛔ அணுகல் மறுக்கப்பட்டது / Access denied")
        return

    # ── 🔥 இன்று DAILY CARD ───────────────────────────────────────────
    if _nav_key == "🔥 இன்று":
        # Need birth data — if no member selected use defaults
        _dc_bdate = bdate if not is_manage else date(1990,1,1)
        _dc_moon_rasi = 0
        try:
            _dc_yr, _dc_mo, _dc_dy = _dc_bdate.year, _dc_bdate.month, _dc_bdate.day
            _dc_hr, _dc_mn = btime.hour, btime.minute
            _, _dc_planets, _ = calc_all_planets(_dc_yr, _dc_mo, _dc_dy,
                                                  _dc_hr, _dc_mn, tz, lat_deg, lon_deg)
            _dc_moon_rasi = get_rasi(_dc_planets["சந்திரன்"])
        except Exception:
            pass
        _render_daily_card(username, _dc_moon_rasi, lat_deg, lon_deg, tz)
        return

    # ── 📅 PANCHANG ──────────────────────────────────────────────────
    if _nav_key == "📅 பஞ்சாங்கம்":
        _render_panchang(panchang_date or date.today(), lat_deg, lon_deg, tz)
        return

    # ── 🔢 NUMEROLOGY ────────────────────────────────────────────────
    if _nav_key == "🔢 எண் கணிதம்":
        _render_numerology(name, bdate)
        return

    # ── 🃏 TAROT ─────────────────────────────────────────────────────
    if _nav_key == "🃏 Tarot":
        _render_tarot(tarot_date or date.today())
        return

    # ── 🔔 REMINDERS ─────────────────────────────────────────────────
    if _nav_key == "🔔 நினைவூட்டல்":
        _render_reminders(lat_deg, lon_deg, tz)
        return

    # ── 📸 IMAGE AI ───────────────────────────────────────────────────
    if _nav_key == "📸 Image AI":
        _render_image_ai()
        return

    # ── 🌟 JADHAGAM / 🔮 HOROSCOPE — both need chart calc ────────────
    if _nav_key == "🌟 ஜாதகம்":
        st.markdown("""
        <div style='text-align:center;padding:10px 0 4px 0;'>
          <h1 style='font-size:2.2rem;margin:0'>🌟 ஜாதகம் Pro</h1>
          <p style='color:#888;margin:0'>Tamil Vedic Astrology · Jadhagam Generator</p>
        </div>""", unsafe_allow_html=True)
        if not st.session_state.get("jadhagam_generated"):
            st.info("👈 பக்கப்பட்டியில் நபரை தேர்ந்தெடுக்கவும் அல்லது Custom நபர் விவரங்களை உள்ளிட்டு "
                    "**✨ ஜாதகம் உருவாக்கு** பொத்தானை அழுத்தவும்.")
            return
    elif _nav_key == "🔮 ராசி கணிப்பு":
        st.markdown("""
        <div style='text-align:center;padding:10px 0 4px 0;'>
          <h1 style='font-size:2.2rem;margin:0'>🔮 ராசி கணிப்பு</h1>
          <p style='color:#888;margin:0'>Daily · Weekly · Monthly · Yearly Horoscope</p>
        </div>""", unsafe_allow_html=True)
        if not st.session_state.get("jadhagam_generated"):
            st.warning("⚠️ பக்கப்பட்டியில் குடும்ப உறுப்பினரை தேர்ந்தெடுக்கவும்.")
            return

    # ── Calculate ───────────────────────────────────────────────────
    yr, mo, dy = bdate.year, bdate.month, bdate.day
    hr, mn_t   = btime.hour, btime.minute
    birth_dt   = datetime(yr, mo, dy, hr, mn_t)

    # All positions via Swiss Ephemeris (accurate to arc-minutes)
    jd, planets, lagna_lon = calc_all_planets(
        yr, mo, dy, hr, mn_t, tz, lat_deg, lon_deg)

    lagna_rasi = get_rasi(lagna_lon)
    moon       = planets["சந்திரன்"]          # shortcut used throughout
    moon_rasi  = get_rasi(moon)
    moon_nak   = get_nak(moon)
    moon_pada  = get_pada(moon)

    # Build rasi chart dict
    chart = {i: [] for i in range(12)}
    chart[lagna_rasi].append("__lagna__")
    for p, lon in planets.items():
        chart[get_rasi(lon)].append(p)

    dasha_tl, active_dasha = calc_vimshottari(birth_dt, moon)
    yogas = detect_yogas(planets, lagna_rasi)
    today = datetime.now()

    # ── Accuracy-enhancing systems ──────────────────────────────────
    combustion_data          = check_combustion(planets)
    retro_data               = check_retrograde(jd)
    aspect_table             = build_aspect_table(planets)
    transit_pos              = calc_gochar(today)
    indiv_ashtak, sarva_ashtak = calc_ashtakavarga(planets, lagna_rasi)
    shadbala_data            = calc_shadbala(planets, lagna_rasi, jd)

    disp_name = name.strip() or "அன்பர்"

    # ── Title bar ───────────────────────────────────────────────────
    st.markdown(f"""
    <div style='background:linear-gradient(90deg,#1e0a3c,#2d1040,#1e0a3c);
         border:1px solid #FF6B35;border-radius:14px;padding:14px 20px;margin-bottom:10px;
         display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px'>
      <div>
        <div style='font-size:1.4rem;font-weight:700;color:#FFB347'>{disp_name} ஜாதகம்</div>
        <div style='color:#888;font-size:0.85rem'>{dy:02d}/{mo:02d}/{yr} · {hr:02d}:{mn_t:02d} · {place or "India"} · UTC+{tz}</div>
      </div>
      <div style='text-align:right'>
        <div style='color:#FF6B35;font-size:0.9rem;font-weight:600'>லக்னம்: {RASI[lagna_rasi]}</div>
        <div style='color:#aaa;font-size:0.85rem'>நட்சத்திரம்: {NAKSHATRA[moon_nak]} பாதம் {moon_pada}</div>
      </div>
    </div>
    """, unsafe_allow_html=True)

    # ── 🔮 Horoscope section routes here (has chart data now) ────────
    if _nav_key == "🔮 ராசி கணிப்பு":
        try:
            h_period = horoscope_period
        except NameError:
            h_period = "இன்று"
        _render_horoscope(moon_rasi, lagna_rasi, dasha_tl, active_dasha,
                          transit_pos, planets, disp_name, h_period)
        return

    # ── Tabs ────────────────────────────────────────────────────────
    tabs = st.tabs(["🌙 Overview", "♈ ராசி", "🔯 Navamsa", "🪐 Planets",
                    "⏳ Dasha", "🔮 Predict", "⭐ Yogas", "🏠 Houses", "💊 Remedies",
                    "🔬 Analysis", "🌍 Gochar", "💑 Match", "🤖 AI வாசிப்பு",
                    "📐 D10·D60", "🔑 KP", "🕉️ Jaimini", "🔔 Transits", "⭐ தாரா"])

    # ════════════════════════════════════════════════════════════════
    # TAB 1 — OVERVIEW
    # ════════════════════════════════════════════════════════════════
    with tabs[0]:
        c1, c2, c3, c4 = st.columns(4)
        def mcard(col, lbl, val):
            col.markdown(f"""<div class='metric-card'>
              <div class='metric-label'>{lbl}</div>
              <div class='metric-value'>{val}</div></div>""", unsafe_allow_html=True)

        mcard(c1, "ஜன்ம ராசி / Moon Sign", f"{RASI[moon_rasi]}\n{RASI_EN[moon_rasi]}")
        mcard(c2, "லக்னம் / Lagna",         f"{RASI[lagna_rasi]}\n{RASI_EN[lagna_rasi]}")
        mcard(c3, "நட்சத்திரம் / Nakshatra", f"{NAKSHATRA[moon_nak]}\n{NAK_EN[moon_nak]}")
        mcard(c4, "பாதம் / Pada",            f"{moon_pada} / 4")

        st.markdown("---")
        c1, c2 = st.columns(2)
        with c1:
            st.markdown("### 🌟 ராசி குணநலன்கள்")
            ta, en, ta_t, en_t = RASI_TRAITS[moon_rasi]
            st.markdown(f"""
            <div style='background:#1e0a3c;border-left:4px solid #FFB347;
                 border-radius:10px;padding:16px;'>
              <div style='font-size:1.05rem;font-weight:700;color:#FFB347'>{ta} ({en})</div>
              <div style='color:#ddd;margin-top:8px'>{ta_t}</div>
              <div style='color:#aaa;font-size:0.85rem;margin-top:4px'>{en_t}</div>
            </div>""", unsafe_allow_html=True)

        with c2:
            st.markdown("### ⭐ நட்சத்திர விவரம்")
            st.markdown(f"""
            <div style='background:#1e0a3c;border-left:4px solid #c8a96e;
                 border-radius:10px;padding:16px;'>
              <table style='width:100%;color:#ddd;font-size:0.88rem;'>
                <tr><td style='color:#888;width:140px'>நட்சத்திரம்</td>
                    <td><b>{NAKSHATRA[moon_nak]}</b> ({NAK_EN[moon_nak]})</td></tr>
                <tr><td style='color:#888'>பாதம்</td><td><b>{moon_pada}</b> / 4</td></tr>
                <tr><td style='color:#888'>நட்சத்திர அதிபதி</td>
                    <td><b>{NAK_LORD[moon_nak]}</b> ({P_EN[NAK_LORD[moon_nak]]})</td></tr>
                <tr><td style='color:#888'>தேவதை / Deity</td><td>{NAK_DEITY[moon_nak]}</td></tr>
                <tr><td style='color:#888'>தன்மை / Quality</td><td>{NAK_QUALITY[moon_nak]}</td></tr>
              </table>
            </div>""", unsafe_allow_html=True)

        st.markdown("---")
        st.markdown("### ⏳ நடப்பு தசா / Current Dasha")
        ad = active_dasha
        remain = (ad["end"] - today).days
        c1,c2,c3,c4 = st.columns(4)
        mcard(c1, "நடப்பு தசா", f"{P_SYM.get(ad['planet'],'')} {ad['planet']}")
        mcard(c2, "தசா ஆரம்பம்", ad["start"].strftime("%d %b %Y"))
        mcard(c3, "தசா முடிவு",  ad["end"].strftime("%d %b %Y"))
