        def fmt_remedy(raw: str) -> str:
            """Convert pipe-separated remedy items to line-break bullets.
            Avoids markdown-table parsing issues with | characters."""
            if not raw or raw == "—":
                return raw
            parts = [p.strip() for p in raw.split("|") if p.strip()]
            return "<br>".join(f"▸ {p}" for p in parts)

        st.markdown(f"#### {P_SYM.get(ap,'')} நடப்பு தசா நிவாரணம் — Current Dasha Remedy ({ap})")
