        # ── D10 Career interpretation ──────────────────────────────
        st.markdown("---")
        st.markdown("#### 🎯 D10 விரிவான தொழில் பகுப்பாய்வு — Career Deep Analysis")
        d10_10th = (d10_lagna + 9) % 12
        d10_10_lord = RASI_LORD[d10_10th]
        d10_lord_rasi = get_rasi(d10_pos.get(d10_10_lord, 0))
        d10_lord_house = (d10_lord_house_n := (d10_lord_rasi - d10_lagna) % 12 + 1)
        d10_lord_stat = planet_status(d10_10_lord, d10_lord_rasi) if d10_10_lord not in ["ராகு","கேது"] else "Active"
