        _day_names_ta = ["திங்கள்","செவ்வாய்","புதன்","வியாழன்","வெள்ளி","சனி","ஞாயிறு"]
        _cal_rows = []
        for _di in range(14):
            _d_date = today + timedelta(days=_di)
            _d_nak  = (_moon_nak_t + _di) % 27
            _d_ti3  = _get_tara(_d_nak)
            _d_td3  = _TARA_DATA[_d_ti3]
