def _daily_lucky(rasi_idx: int, today: date) -> dict:
    """Return lucky color, number, gem, mantra, good time for today."""
    seed = rasi_idx * 1000 + today.toordinal()
    import hashlib as _hl
    h = int(_hl.md5(str(seed).encode()).hexdigest(), 16)
    color_idx   = (rasi_idx + today.weekday() + today.day) % 12
    lucky_num   = ((h % 8) + 1)
    lucky_time_h= 6 + (h % 12)
    lucky_time  = f"{lucky_time_h:02d}:00 – {lucky_time_h+1:02d}:00"
    gems = ["மாணிக்கம் (Ruby)","முத்து (Pearl)","பவளம் (Coral)","மரகதம் (Emerald)",
            "புஷ்பராகம் (Yellow Sapphire)","வைரம் (Diamond)","நீலம் (Blue Sapphire)",
            "கோமேதகம் (Hessonite)","வைடூரியம் (Cat's Eye)"]
    mantra_map = [
        "ஓம் ஶ்ரீம் ஹ்ரீம் க்லீம் (ஆதித்யாய நமஹ)",
        "ஓம் சோம் சோமாய நமஹ",
        "ஓம் க்ரம் க்ரீம் க்ரோம் ஸஹ் (குஜாய நமஹ)",
        "ஓம் ப்ரம் ப்ரீம் ப்ரோம் ஸஹ் (புதாய நமஹ)",
        "ஓம் க்ரம் க்ரீம் க்ரோம் ஸஹ் (குரவே நமஹ)",
        "ஓம் ஶ்ரம் ஶ்ரீம் ஶ்ரோம் ஸஹ் (ஶுக்ராய நமஹ)",
        "ஓம் ஶம் ஶனிஶ்சராய நமஹ",
        "ஓம் ரம் ராஹவே நமஹ",
        "ஓம் கம் கேதவே நமஹ",
    ]
    return {
        "color":       _COLOR_NAMES[color_idx],
        "color_hex":   _LUCKY_COLORS[color_idx],
        "number":      lucky_num,
        "time":        lucky_time,
        "gem":         gems[rasi_idx % 9],
        "mantra":      mantra_map[rasi_idx % 9],
    }


def _planet_energy_score(today: date, lat: float, lon: float, tz: float) -> dict:
    """Calculate today's planetary energy scores based on live transits."""
    now = datetime.combine(today, datetime.min.time().replace(hour=12))
    try:
        _, t_planets, _ = calc_all_planets(
            now.year, now.month, now.day, 12, 0, tz, lat, lon)
    except Exception:
        t_planets = {}

    scores = {}
    for p in ["சூரியன்","சந்திரன்","செவ்வாய்","புதன்","குரு","சுக்கிரன்","சனி"]:
        lon_p = t_planets.get(p, 0)
        r = get_rasi(lon_p)
        # Higher score = better energy (exalt=10, own=8, neutral=6, debil=3)
        if p in EXALT and EXALT[p] == r:
            score = 10
        elif p in DEBIL and DEBIL[p] == r:
            score = 2
        elif p in OWN and r in OWN[p]:
            score = 8
        else:
            score = 5 + int((lon_p % 30) / 10)   # 5–7 based on degree
        scores[p] = min(10, score)
    return scores


