    st.markdown("---")

    # ── Planet Energy Scores ─────────────────────────────────────────
    st.markdown("### 🪐 இன்றைய கிரக ஆற்றல் — Planet Energy Scores")
    st.caption("இன்று ஒவ்வொரு கிரகமும் எந்த ராசியில் உள்ளது என்பதை அடிப்படையாகக் கொண்டு")
