def _render_panchang(p_date, lat, lon, tz):
    """Full Panchang page."""
    st.markdown("""
    <div style='text-align:center;padding:10px 0 4px 0;'>
      <h1 style='font-size:2.2rem;margin:0'>📅 பஞ்சாங்கம்</h1>
      <p style='color:#888;margin:0'>Daily Vedic Almanac — திருநாள் தகவல்கள்</p>
    </div>""", unsafe_allow_html=True)

    pg = calc_panchang(datetime.combine(p_date, datetime.min.time()), lat, lon, tz)

    # ── Top date banner ─────────────────────────────────────────────
    vara_color = {"ஞாயிறு":"#FFA500","திங்கள்":"#C0C0C0","செவ்வாய்":"#FF4444",
                  "புதன்":"#44FF88","வியாழன்":"#FFD700","வெள்ளி":"#FFAAFF","சனி":"#8888FF"}
    v_col = vara_color.get(pg["vara"], "#FFB347")
    st.markdown(f"""
    <div style='background:linear-gradient(90deg,#1e0a3c,#2d1040,#1e0a3c);
         border:2px solid {v_col};border-radius:14px;padding:16px 22px;margin-bottom:14px;
         display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px'>
      <div>
        <div style='font-size:1.6rem;font-weight:700;color:{v_col}'>{pg["vara"]} — {pg["vara_en"]}</div>
        <div style='color:#aaa;font-size:0.9rem'>{pg["date_str"]} · {pg["sunrise"]} sunrise · {pg["sunset"]} sunset</div>
      </div>
      <div style='text-align:right'>
        <div style='color:#FFB347;font-size:1.1rem;font-weight:600'>{pg["paksha"]}</div>
        <div style='color:#888;font-size:0.85rem'>வார அதிபதி: {pg["vara_lord"]}</div>
      </div>
    </div>""", unsafe_allow_html=True)

    # ── Pancha Anga (5 limbs) ───────────────────────────────────────
    st.markdown("### 🌿 பஞ்சாங்க ஐந்து அங்கங்கள் — Five Limbs")
    col1, col2, col3, col4, col5 = st.columns(5)
    limbs = [
        (col1, "📅 வாரம்",       pg["vara"],       pg["vara_en"],      v_col),
        (col2, "🌙 திதி",         pg["tithi"],      pg["tithi_en"],    "#C0C0C0"),
        (col3, "⭐ நட்சத்திரம்", pg["nakshatra"],  pg["nak_en"],      "#FFD700"),
        (col4, "☯️ யோகம்",        pg["yoga"],       "Panchang Yoga",   "#44FF88" if pg["yoga_good"] else "#FF8844"),
        (col5, "🌀 கரணம்",        pg["karana"],     "Karana",          "#FFAAFF"),
    ]
    for col, label, val, sub, clr in limbs:
        col.markdown(f"""<div class='metric-card' style='border-color:{clr}'>
          <div class='metric-label'>{label}</div>
          <div class='metric-value' style='color:{clr}'>{val}</div>
          <div style='font-size:0.75rem;color:#888;margin-top:4px'>{sub}</div>
        </div>""", unsafe_allow_html=True)

    # Tithi & Nakshatra progress bars
    st.markdown("---")
    c1, c2 = st.columns(2)
    with c1:
        st.markdown(f"**🌙 திதி நிலை ({pg['tithi_pct']}% நிறைவு)**")
        st.progress(pg["tithi_pct"] / 100)
        st.caption(f"{pg['paksha']} · {pg['tithi']} ({pg['tithi_en']})")
    with c2:
        st.markdown(f"**⭐ நட்சத்திர நிலை ({pg['nak_pct']}% நிறைவு)**")
        st.progress(pg["nak_pct"] / 100)
        st.caption(f"{pg['nakshatra']} · அதிபதி: {pg['nak_lord']}")

    # ── Sunrise / Sunset / Muhurthas ───────────────────────────────
    st.markdown("### ☀️ சூரியோதயம் / மறைவு — Sunrise & Sunset")
    sc1, sc2, sc3, sc4 = st.columns(4)
    sc1.markdown(f"""<div class='metric-card' style='border-color:#FFA500'>
      <div class='metric-label'>🌅 சூரியோதயம்</div>
      <div class='metric-value' style='color:#FFA500'>{pg["sunrise"]}</div>
      <div style='font-size:0.75rem;color:#888'>Sunrise</div></div>""", unsafe_allow_html=True)
    sc2.markdown(f"""<div class='metric-card' style='border-color:#FF6B35'>
      <div class='metric-label'>🌇 சூரியாஸ்தமனம்</div>
      <div class='metric-value' style='color:#FF6B35'>{pg["sunset"]}</div>
      <div style='font-size:0.75rem;color:#888'>Sunset</div></div>""", unsafe_allow_html=True)
    sc3.markdown(f"""<div class='metric-card' style='border-color:#FFD700'>
      <div class='metric-label'>✨ அபிஜித் முஹூர்த்தம்</div>
      <div class='metric-value' style='color:#FFD700;font-size:0.95rem'>{pg["abhijit"]}</div>
      <div style='font-size:0.75rem;color:#888'>Most Auspicious</div></div>""", unsafe_allow_html=True)
    sc4.markdown(f"""<div class='metric-card' style='border-color:#9966CC'>
      <div class='metric-label'>🌄 ப்ரம்ம முஹூர்த்தம்</div>
      <div class='metric-value' style='color:#9966CC;font-size:0.95rem'>{pg["brahma"]}</div>
      <div style='font-size:0.75rem;color:#888'>Pre-Dawn</div></div>""", unsafe_allow_html=True)

    # ── Inauspicious Periods ────────────────────────────────────────
    st.markdown("### ⛔ தீய நேரங்கள் — Inauspicious Periods")
    ic1, ic2, ic3 = st.columns(3)
    ic1.markdown(f"""<div style='background:#1f0505;border:2px solid #FF4444;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#FF4444;font-weight:700;font-size:1.0rem'>☊ ராகு காலம்</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["rahu_kalam"]}</div>
      <div style='color:#888;font-size:0.78rem;margin-top:4px'>Rahu Kalam — தவிர்க்கவும்</div>
    </div>""", unsafe_allow_html=True)
    ic2.markdown(f"""<div style='background:#1a0f00;border:2px solid #FF8844;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#FF8844;font-weight:700;font-size:1.0rem'>⚡ யமகண்டம்</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["yamagandam"]}</div>
      <div style='color:#888;font-size:0.78rem;margin-top:4px'>Yamagandam — தவிர்க்கவும்</div>
    </div>""", unsafe_allow_html=True)
    ic3.markdown(f"""<div style='background:#0a0a1f;border:2px solid #8888FF;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#8888FF;font-weight:700;font-size:1.0rem'>🪐 குளிகை</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["gulikai"]}</div>
      <div style='color:#888;font-size:0.78rem;margin-top:4px'>Gulikai — கவனம்</div>
    </div>""", unsafe_allow_html=True)

    # ── Upcoming Tamil Festivals ────────────────────────────────────
    st.markdown("---")
    st.markdown("### 🎊 வரவிருக்கும் திருநாட்கள் — Upcoming Festivals")
    today_dt = datetime.combine(p_date, datetime.min.time())
    upcoming = []
    for yr_offset in [0, 1]:
        for f in TAMIL_FESTIVALS:
            try:
                fdt = datetime(p_date.year + yr_offset, f["month"], f["day"])
                if fdt >= today_dt:
                    days_away = (fdt - today_dt).days
                    upcoming.append({**f, "date": fdt, "days_away": days_away})
            except ValueError:
                pass
    upcoming.sort(key=lambda x: x["days_away"])
    for f in upcoming[:6]:
        badge = "🟢 இன்று!" if f["days_away"] == 0 else (f"🟡 {f['days_away']} நாளில்" if f["days_away"] <= 7 else f"📅 {f['days_away']} நாளில்")
        st.markdown(f"""<div style='background:#1e0a3c;border-left:4px solid #FFD700;
             border-radius:8px;padding:10px 14px;margin-bottom:6px;display:flex;
             justify-content:space-between;align-items:center'>
          <div>
            <span style='color:#FFB347;font-weight:600'>{f["name"]}</span>
            <span style='color:#aaa;font-size:0.85rem;margin-left:8px'>{f["date"].strftime("%d %b %Y")}</span><br>
            <span style='color:#888;font-size:0.82rem'>{f["desc"]}</span>
          </div>
          <div style='color:#FFD700;font-size:0.85rem;text-align:right;white-space:nowrap'>{badge}</div>
        </div>""", unsafe_allow_html=True)

    # ── Pancha Pakshi (simplified) ──────────────────────────────────
    st.markdown("---")
    st.markdown("### 🦅 பஞ்ச பட்சி — Five Bird System")
    PAKSHI_BIRDS = ["கழுகு (Vulture)","ஆந்தை (Owl)","காகம் (Crow)","சேவல் (Cock)","மயில் (Peacock)"]
    PAKSHI_ACTS  = ["ஆட்சி (Rule)","சாப்பிடுதல் (Eat)","நடத்தல் (Walk)","குடிக்கல் (Drink)","உறங்குதல் (Sleep)"]
    PAKSHI_COLORS= ["#FFD700","#9966CC","#888888","#FF6B35","#44FF88"]
    vara_bird_idx = pg["vara_idx"]
    day_bird = PAKSHI_BIRDS[vara_bird_idx % 5]
    st.info(f"🦅 இன்றைய பிரதான பட்சி: **{day_bird}** — வார அடிப்படையில் செயல்கள் திட்டமிடலாம்")
    pb_cols = st.columns(5)
    for i, (bird, act, clr) in enumerate(zip(PAKSHI_BIRDS, PAKSHI_ACTS, PAKSHI_COLORS)):
        pb_cols[i].markdown(f"""<div style='background:#1e0a3c;border:1px solid {clr};
             border-radius:10px;padding:10px;text-align:center;font-size:0.82rem'>
          <div style='color:{clr};font-weight:700'>{bird.split("(")[0].strip()}</div>
          <div style='color:#ddd;margin-top:4px'>{act.split("(")[0].strip()}</div>
          <div style='color:#666;font-size:0.72rem'>{bird.split("(")[1].rstrip(")")}</div>
        </div>""", unsafe_allow_html=True)


def _render_numerology(name, bdate):
    """Numerology section."""
    st.markdown("""
    <div style='text-align:center;padding:10px 0 4px 0;'>
      <h1 style='font-size:2.2rem;margin:0'>🔢 எண் கணிதம்</h1>
      <p style='color:#888;margin:0'>Vedic Numerology — உங்கள் எண்ணின் இரகசியம்</p>
    </div>""", unsafe_allow_html=True)

    if not name.strip():
        st.warning("⚠️ பக்கப்பட்டியில் உங்கள் பெயரை உள்ளிடவும் — Enter your name in the sidebar.")
        return

    num = calc_numerology(name.strip(), bdate)
    lp  = num["life_path"]
    nn  = num["name_num"]
    lpi = num["lp_info"]
    nni = num["nn_info"]

    # ── Banner ──────────────────────────────────────────────────────
    lp_clr = lpi.get("color","#FFB347")
    st.markdown(f"""
    <div style='background:linear-gradient(135deg,#1e0a3c,#2d1040);
         border:2px solid {lp_clr};border-radius:14px;padding:18px 24px;margin-bottom:16px'>
      <div style='font-size:1.3rem;font-weight:700;color:{lp_clr};margin-bottom:4px'>
        🔢 {name.strip()} — ஜீவன பாத எண் {lp}</div>
      <div style='color:#aaa;font-size:0.88rem'>
        பிறந்த தேதி: {bdate.strftime("%d/%m/%Y")} ·
        கூட்டுத்தொகை: {num["raw_total"]} → குறைந்தது: {lp}
      </div>
    </div>""", unsafe_allow_html=True)

    # ── Two main numbers ─────────────────────────────────────────────
    c1, c2 = st.columns(2)
    with c1:
        st.markdown(f"""
        <div style='background:#1e0a3c;border:2px solid {lp_clr};border-radius:14px;
             padding:20px;text-align:center'>
          <div style='font-size:3.5rem;font-weight:900;color:{lp_clr}'>{lp}</div>
          <div style='color:#FFB347;font-size:1.05rem;font-weight:700;margin-top:6px'>
            ஜீவன பாத எண் / Life Path Number</div>
          <div style='color:#ddd;font-size:0.88rem;margin-top:8px'>{lpi.get("title","")}</div>
        </div>""", unsafe_allow_html=True)
        if lpi:
            st.markdown(f"""
            <div style='background:#0f0a1e;border-left:3px solid {lp_clr};
                 border-radius:8px;padding:14px;margin-top:10px'>
              <div style='color:#ddd;font-size:0.9rem;line-height:1.7'>{lpi.get("desc","")}</div>
            </div>""", unsafe_allow_html=True)

    nn_clr = nni.get("color","#C0C0C0") if nni else "#C0C0C0"
    with c2:
        st.markdown(f"""
        <div style='background:#1e0a3c;border:2px solid {nn_clr};border-radius:14px;
             padding:20px;text-align:center'>
          <div style='font-size:3.5rem;font-weight:900;color:{nn_clr}'>{nn}</div>
          <div style='color:#FFB347;font-size:1.05rem;font-weight:700;margin-top:6px'>
            பெயர் எண் / Name Number (Chaldean)</div>
          <div style='color:#ddd;font-size:0.88rem;margin-top:8px'>{nni.get("title","") if nni else ""}</div>
        </div>""", unsafe_allow_html=True)
        if nni:
            st.markdown(f"""
            <div style='background:#0f0a1e;border-left:3px solid {nn_clr};
                 border-radius:8px;padding:14px;margin-top:10px'>
              <div style='color:#ddd;font-size:0.9rem;line-height:1.7'>{nni.get("desc","")}</div>
            </div>""", unsafe_allow_html=True)

    # ── Lucky Details ───────────────────────────────────────────────
    st.markdown("---")
    st.markdown("### 🍀 அதிர்ஷ்ட விவரங்கள் — Lucky Details")
    if lpi:
        lc1, lc2, lc3, lc4 = st.columns(4)
        lc1.markdown(f"""<div class='metric-card' style='border-color:{lp_clr}'>
          <div class='metric-label'>🎯 அதிர்ஷ்ட எண்கள்</div>
          <div class='metric-value' style='color:{lp_clr}'>{", ".join(str(n) for n in lpi.get("lucky_num",[]))}</div>
          <div style='font-size:0.72rem;color:#888'>Lucky Numbers</div></div>""", unsafe_allow_html=True)
        lc2.markdown(f"""<div class='metric-card' style='border-color:{lp_clr}'>
          <div class='metric-label'>📅 அதிர்ஷ்ட நாள்</div>
          <div class='metric-value' style='color:{lp_clr}'>{lpi.get("lucky_day","")}</div>
          <div style='font-size:0.72rem;color:#888'>Lucky Day</div></div>""", unsafe_allow_html=True)
        lc3.markdown(f"""<div class='metric-card' style='border-color:{lp_clr}'>
          <div class='metric-label'>🎨 அதிர்ஷ்ட நிறம்</div>
          <div class='metric-value' style='color:{lp_clr}'>{lpi.get("lucky_color","")}</div>
          <div style='font-size:0.72rem;color:#888'>Lucky Color</div></div>""", unsafe_allow_html=True)
        lc4.markdown(f"""<div class='metric-card' style='border-color:{lp_clr}'>
          <div class='metric-label'>💎 ரத்தினக்கல்</div>
          <div class='metric-value' style='color:{lp_clr};font-size:0.95rem'>{lpi.get("stone","")}</div>
          <div style='font-size:0.72rem;color:#888'>Lucky Stone</div></div>""", unsafe_allow_html=True)

    # ── Compatibility grid ──────────────────────────────────────────
    st.markdown("---")
    st.markdown("### 🤝 எண் பொருத்தம் — Number Compatibility")
    compat = {
        1:[1,5,9], 2:[2,4,8], 3:[3,6,9], 4:[1,2,7], 5:[1,5,6],
        6:[3,5,6], 7:[1,2,7], 8:[2,4,8], 9:[1,3,9],
    }
    best_nums = compat.get(lp % 9 or 9, [])
    compat_cols = st.columns(9)
    for i, col in enumerate(compat_cols):
        n = i + 1
        is_best   = n in best_nums
        is_self   = n == lp
        bg = "#1a2e1a" if is_best else ("#2e1a00" if is_self else "#1e0a3c")
        bd = "#44FF88" if is_best else ("#FF6B35" if is_self else "#444")
        col.markdown(f"""<div style='background:{bg};border:2px solid {bd};border-radius:10px;
             padding:10px;text-align:center'>
          <div style='font-size:1.4rem;font-weight:700;color:{bd}'>{n}</div>
          <div style='font-size:0.6rem;color:#888'>{"✅ Best" if is_best else ("🌟 You" if is_self else "")}</div>
        </div>""", unsafe_allow_html=True)
    st.caption("✅ Best = most compatible numbers  |  🌟 You = your Life Path number")

    # ── Name analysis ───────────────────────────────────────────────
    st.markdown("---")
    with st.expander("🔤 பெயர் எண் கணக்கீடு — Name Number Calculation (Chaldean)"):
        letters = [c.lower() for c in name.strip() if c.isalpha()]
        values  = [CHALDEAN_MAP.get(c, 0) for c in letters]
        tbl = pd.DataFrame({
            "எழுத்து / Letter": [c.upper() for c in letters],
            "Chaldean Value":    values,
        })
        st.dataframe(tbl.T, use_container_width=True)
        st.markdown(f"**மொத்தம் / Total: {sum(values)} → குறைந்தது / Reduced: {nn}**")
        st.caption("Chaldean Numerology: A=1, B=2, C=3, D=4, E=5, F=8, G=3, H=5, I=1...")


def _render_tarot(t_date):
    """Daily Tarot card section."""
    st.markdown("""
    <div style='text-align:center;padding:10px 0 4px 0;'>
      <h1 style='font-size:2.2rem;margin:0'>🃏 Daily Tarot</h1>
      <p style='color:#888;margin:0'>Major Arcana · இன்றைய தாரோ அட்டை</p>
    </div>""", unsafe_allow_html=True)

    card = get_daily_tarot(t_date)

    # ── Card display ─────────────────────────────────────────────────
    st.markdown(f"""
    <div style='background:linear-gradient(135deg,#1a0035,#2d0060,#1a0035);
         border:3px solid #9966CC;border-radius:20px;padding:30px;
         text-align:center;max-width:500px;margin:20px auto'>
      <div style='font-size:5rem;margin-bottom:10px'>{card["icon"]}</div>
      <div style='font-size:0.85rem;color:#9966CC;letter-spacing:2px;
           text-transform:uppercase;margin-bottom:6px'>{card["num"]} · Major Arcana</div>
      <div style='font-size:2rem;font-weight:700;color:#E0BBFF;margin-bottom:4px'>
        {card["name"]}</div>
      <div style='font-size:1.1rem;color:#FFD700;margin-bottom:20px'>{card["tm"]}</div>
      <div style='height:2px;background:linear-gradient(90deg,transparent,#9966CC,transparent);
           margin-bottom:20px'></div>
      <div style='color:#ddd;font-size:0.95rem;line-height:1.8;text-align:left'>
        <span style='color:#44FF88;font-weight:700'>✅ நேர் நிலை (Upright):</span><br>
        {card["upright"]}<br><br>
        <span style='color:#FF8844;font-weight:700'>🔄 தலைகீழ் (Reversed):</span><br>
        {card["reverse"]}
      </div>
    </div>""", unsafe_allow_html=True)

    # ── Date context ─────────────────────────────────────────────────
    st.markdown(f"<p style='text-align:center;color:#888;font-size:0.85rem'>"
                f"🗓️ {t_date.strftime('%d %B %Y')} — இந்த தேதிக்கான அட்டை</p>",
                unsafe_allow_html=True)

    # ── All 22 cards ─────────────────────────────────────────────────
    st.markdown("---")
    with st.expander("🃏 அனைத்து 22 Major Arcana அட்டைகளும் — Full Deck"):
        card_cols = st.columns(4)
        for i, c in enumerate(TAROT_MAJOR):
            is_today = (c["name"] == card["name"])
            bg = "#1a0035" if is_today else "#0f0a1e"
            bd = "#9966CC" if is_today else "#333"
            hl = " ⬅ இன்று" if is_today else ""
            card_cols[i % 4].markdown(f"""
            <div style='background:{bg};border:1px solid {bd};border-radius:10px;
                 padding:10px;text-align:center;margin-bottom:8px'>
              <div style='font-size:1.8rem'>{c["icon"]}</div>
              <div style='color:#9966CC;font-size:0.72rem'>{c["num"]}</div>
              <div style='color:#ddd;font-size:0.8rem;font-weight:600'>{c["name"]}{hl}</div>
              <div style='color:#FFD700;font-size:0.72rem'>{c["tm"]}</div>
            </div>""", unsafe_allow_html=True)


def _render_horoscope(moon_rasi, lagna_rasi, dasha_tl, active_dasha,
                      transit_pos, planets, disp_name, period):
    """Transit-based Rasi Horoscope section."""
    period_icons = {"இன்று":"☀️","இந்த வாரம்":"📅","இந்த மாதம்":"🌙","இந்த ஆண்டு":"🌟"}
    p_icon = period_icons.get(period, "🔮")

    st.markdown(f"""
    <div style='background:linear-gradient(135deg,#1e0a3c,#2d1040);
         border:2px solid #FF6B35;border-radius:14px;padding:16px 22px;margin-bottom:14px'>
      <div style='font-size:1.3rem;font-weight:700;color:#FFB347'>{p_icon} {disp_name} — {period} ராசி கணிப்பு</div>
      <div style='color:#aaa;font-size:0.88rem;margin-top:4px'>
        ஜன்ம ராசி: {RASI[moon_rasi]} ({RASI_EN[moon_rasi]}) ·
        லக்னம்: {RASI[lagna_rasi]} ·
        நடப்பு தசா: {active_dasha["planet"]} ({active_dasha["start"].strftime("%Y")}–{active_dasha["end"].strftime("%Y")})
      </div>
    </div>""", unsafe_allow_html=True)

    # ── Period tabs ─────────────────────────────────────────────────
    ptabs = st.tabs(["☀️ இன்று", "📅 இந்த வாரம்", "🌙 இந்த மாதம்", "🌟 இந்த ஆண்டு"])

    today = datetime.now()
    preds, highlights = daily_horoscope_text(moon_rasi, transit_pos)

    # Shared domain cards renderer
    def _domain_cards(predictions, extra_note=""):
        domains = [
            ("💼 தொழில்",  "career",  "#FFD700"),
            ("❤️ காதல்",   "love",    "#FF6B35"),
            ("💪 ஆரோக்கியம்","health","#44FF88"),
            ("💰 நிதி",    "finance", "#C0C0C0"),
        ]
        dc = st.columns(2)
        for i, (label, key, clr) in enumerate(domains):
            dc[i % 2].markdown(f"""
            <div style='background:#1e0a3c;border-left:4px solid {clr};
                 border-radius:10px;padding:14px;margin-bottom:10px'>
              <div style='color:{clr};font-weight:700;font-size:0.95rem;margin-bottom:6px'>{label}</div>
              <div style='color:#ddd;font-size:0.88rem;line-height:1.7'>{predictions.get(key,"")}</div>
            </div>""", unsafe_allow_html=True)
        if extra_note:
            st.info(extra_note)
        if highlights:
            with st.expander("🔭 கோசார சிறப்பு விளைவுகள் — Transit Highlights"):
                for h in highlights:
                    st.markdown(f"• {h}")

    with ptabs[0]:  # Today
        st.markdown(f"#### ☀️ {today.strftime('%d %B %Y')} — இன்றைய கணிப்பு")
        # Moon transit for today
        moon_transit_rasi = get_rasi(transit_pos.get("சந்திரன்", 0))
        moon_house = (moon_transit_rasi - moon_rasi) % 12 + 1
        moon_msgs = {1:"சந்திரன் ஜன்ம ராசியில் — உணர்வு மாற்றங்கள் இருக்கலாம்.",
                     5:"காதல், படைப்பாற்றல், குழந்தை விஷயங்களில் நல்ல நாள்.",
                     11:"லாப ஸ்தானத்தில் சந்திரன் — வருமான வாய்ப்பு இருக்கலாம்.",
                     9:"தர்ம ஸ்தானம் — ஆன்மீக, தெய்வீக செயல்களுக்கு நல்ல நாள்.",
                     10:"தொழிலில் கவனம் — முக்கியமான முடிவுகள் எடுக்க நல்ல நாள்."}
        moon_msg = moon_msgs.get(moon_house, f"சந்திரன் {moon_house}ம் வீட்டில் — சாதாரண நாள்.")
        st.caption(f"🌙 சந்திர கோசாரம்: {RASI[moon_transit_rasi]} ({moon_house}ம் வீடு) — {moon_msg}")
        _domain_cards(preds)

        # Dasha note
        ad_list = calc_antardasha(active_dasha)
        today_ad = next((a for a in ad_list if a["start"] <= today <= a["end"]), None)
        if today_ad:
            st.markdown(f"""
            <div style='background:#0f0a1e;border:1px solid #9966CC;border-radius:10px;padding:12px;margin-top:10px'>
              <span style='color:#9966CC;font-weight:700'>⏳ நடப்பு தசா-அந்தர்தசா:</span>
              <span style='color:#ddd'> {active_dasha["planet"]} MD · {today_ad["planet"]} AD
              ({today_ad["start"].strftime("%b %Y")} – {today_ad["end"].strftime("%b %Y")})</span>
            </div>""", unsafe_allow_html=True)

    with ptabs[1]:  # This week
        st.markdown(f"#### 📅 {today.strftime('%d %b')} – {(today + timedelta(days=6)).strftime('%d %b %Y')}")
        week_theme = WEEKLY_THEMES[today.weekday()]
        st.info(f"🌟 இந்த வாரத்தின் சிறப்பு: {week_theme}")
        # Slightly enhanced predictions for week
        week_preds = {k: v + " இந்த வாரம் முழுவதும் இந்த தாக்கம் இருக்கும்."
                      for k, v in preds.items()}
        _domain_cards(week_preds, "")

    with ptabs[2]:  # This month
        st.markdown(f"#### 🌙 {today.strftime('%B %Y')} — மாத கணிப்பு")
        # Which dashas active this month
        month_start = today.replace(day=1)
        month_end   = (month_start + timedelta(days=32)).replace(day=1) - timedelta(days=1)
        active_ants = []
        for d in dasha_tl:
            if d["end"] < month_start or d["start"] > month_end:
                continue
            for a in calc_antardasha(d):
                if a["end"] >= month_start and a["start"] <= month_end:
                    active_ants.append((d["planet"], a["planet"]))
                    break
        if active_ants:
            ant_str = " → ".join([f"{m}/{a}" for m, a in active_ants[:3]])
            st.caption(f"⏳ இந்த மாதம் தசா: {ant_str}")
        month_preds = {
            "career": f"இந்த மாதம் {active_dasha['planet']} தசாவில் தொழில் முன்னேற்றம் — " + preds["career"],
            "love":   preds["love"] + " திருமண யோசனைகள் முன்னேறலாம்.",
            "health": preds["health"] + " மாத இறுதியில் உடல் பரிசோதனை நல்லது.",
            "finance": preds["finance"] + f" {today.strftime('%B')} மாதம் நிதி திட்டமிடல் அவசியம்.",
        }
        _domain_cards(month_preds)

    with ptabs[3]:  # This year
        st.markdown(f"#### 🌟 {today.year} — ஆண்டு கணிப்பு")
        # Annual forecast using get_annual_forecast
        try:
            annual = get_annual_forecast(today.year, dasha_tl, planets, lagna_rasi)
        except Exception:
            annual = []

        if annual:
            st.markdown("##### 📆 ஆண்டு தசா அட்டவணை")
            for item in annual[:6]:
                label_color = "#44ff88" if "மிகவும்" in item.get("label","") else (
                    "#FF4444" if "கடினம்" in item.get("label","") else "#FFB347")
                with st.expander(f"{item.get('label','')} · {item['md']} MD / {item['ad']} AD  ({item.get('period_str','')})"):
                    yc1, yc2 = st.columns(2)
                    yc1.markdown(f"""
                    <div style='background:#1e0a3c;border-radius:8px;padding:10px'>
                      <div style='color:#FFD700;font-weight:700;margin-bottom:6px'>💼 தொழில்</div>
                      <div style='color:#ddd;font-size:0.88rem'>{item.get('career','')}</div>
                    </div>""", unsafe_allow_html=True)
                    yc2.markdown(f"""
                    <div style='background:#1e0a3c;border-radius:8px;padding:10px'>
                      <div style='color:#C0C0C0;font-weight:700;margin-bottom:6px'>💰 நிதி</div>
                      <div style='color:#ddd;font-size:0.88rem'>{item.get('finance','')}</div>
                    </div>""", unsafe_allow_html=True)
                    if item.get("highlight"):
                        st.success(f"✨ சிறப்பு: {item['highlight']}")
        else:
            year_preds = {
                "career": f"{today.year}-ல் {active_dasha['planet']} தசா — " + preds["career"],
                "love":   "இந்த ஆண்டு காதல், திருமண விஷயங்களில் முக்கியமான மாற்றங்கள் வரலாம்.",
                "health": "ஆண்டு முழுவதும் ஆரோக்கியத்தில் கவனம் செலுத்துவது நல்லது.",
                "finance":f"{active_dasha['planet']} தசாவில் நிதி: " + preds["finance"],
            }
            _domain_cards(year_preds)

    # ── Rasi comparison for all 12 signs ────────────────────────────
    st.markdown("---")
    with st.expander("🌐 அனைத்து 12 ராசிகளுக்கும் இன்றைய கோசார நிலை"):
        all_cols = st.columns(4)
        for ri in range(12):
            hp = (get_rasi(transit_pos.get("குரு", 0)) - ri) % 12 + 1
            hs = (get_rasi(transit_pos.get("சனி", 0)) - ri) % 12 + 1
            hm = (get_rasi(transit_pos.get("செவ்வாய்",0)) - ri) % 12 + 1
            score = (1 if hp in [1,5,9,11] else -1 if hp in [6,8,12] else 0) + \
                    (1 if hs in [3,6,11]   else -1 if hs in [1,4,8,12] else 0) + \
                    (-1 if hm in [1,4,7,8] else 1 if hm in [3,6,11] else 0)
            clr = "#44FF88" if score > 0 else ("#FF4444" if score < 0 else "#FFB347")
            star = "⭐" if ri == moon_rasi else ""
            all_cols[ri % 4].markdown(f"""
            <div style='background:#1e0a3c;border:1px solid {clr};border-radius:8px;
                 padding:8px;text-align:center;margin-bottom:6px'>
              <div style='color:{clr};font-weight:700;font-size:0.88rem'>{RASI[ri]}{star}</div>
              <div style='color:#888;font-size:0.72rem'>{RASI_EN[ri]}</div>
              <div style='color:{clr};font-size:0.8rem;margin-top:2px'>
                {"🟢 சாதகம்" if score>0 else ("🔴 சவால்" if score<0 else "🟡 சாதாரண")}</div>
            </div>""", unsafe_allow_html=True)
        st.caption("⭐ = உங்கள் ஜன்ம ராசி  |  குரு/சனி/செவ்வாய் கோசார நிலையை வைத்து கணக்கிட்டது")


def _render_reminders(lat, lon, tz):
    """Daily Reminders & Alerts section."""
    st.markdown("""
    <div style='text-align:center;padding:10px 0 4px 0;'>
      <h1 style='font-size:2.2rem;margin:0'>🔔 நினைவூட்டல்கள்</h1>
      <p style='color:#888;margin:0'>Daily Reminders · Auspicious Timings · Festival Alerts</p>
    </div>""", unsafe_allow_html=True)

    today = date.today()
    today_dt = datetime.now()
    pg = calc_panchang(datetime.combine(today, datetime.min.time()), lat, lon, tz)

    # ── Today's quick summary card ──────────────────────────────────
    vara_color = {"ஞாயிறு":"#FFA500","திங்கள்":"#C0C0C0","செவ்வாய்":"#FF4444",
                  "புதன்":"#44FF88","வியாழன்":"#FFD700","வெள்ளி":"#FFAAFF","சனி":"#8888FF"}
    v_col = vara_color.get(pg["vara"], "#FFB347")
    st.markdown(f"""
    <div style='background:linear-gradient(90deg,#1e0a3c,#2d1040,#1e0a3c);
         border:2px solid {v_col};border-radius:12px;padding:14px 20px;margin-bottom:14px'>
      <div style='font-size:1.2rem;font-weight:700;color:{v_col}'>
        📅 {today.strftime("%d %B %Y")} — {pg["vara"]} ({pg["vara_en"]})</div>
      <div style='color:#ddd;font-size:0.9rem;margin-top:8px;display:flex;flex-wrap:wrap;gap:16px'>
        <span>🌙 திதி: <b>{pg["tithi"]}</b></span>
        <span>⭐ நட்சத்திரம்: <b>{pg["nakshatra"]}</b></span>
        <span>☯️ யோகம்: <b>{pg["yoga"]}</b> {"✅" if pg["yoga_good"] else "⚠️"}</span>
        <span>🌅 சூரியோதயம்: <b>{pg["sunrise"]}</b></span>
        <span>🌇 அஸ்தமனம்: <b>{pg["sunset"]}</b></span>
      </div>
    </div>""", unsafe_allow_html=True)

    # ── Today's timings at a glance ─────────────────────────────────
    st.markdown("### ⏰ இன்றைய முக்கிய நேரங்கள்")
    tc = st.columns(3)
    tc[0].markdown(f"""
    <div style='background:#0a1500;border:2px solid #44FF88;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#44FF88;font-weight:700'>✨ அபிஜித் முஹூர்த்தம்</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["abhijit"]}</div>
      <div style='color:#888;font-size:0.78rem'>Most auspicious · முக்கிய காரியங்களுக்கு</div>
    </div>""", unsafe_allow_html=True)
    tc[1].markdown(f"""
    <div style='background:#1f0505;border:2px solid #FF4444;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#FF4444;font-weight:700'>⛔ ராகு காலம்</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["rahu_kalam"]}</div>
      <div style='color:#888;font-size:0.78rem'>Avoid new work · புதிய காரியம் வேண்டாம்</div>
    </div>""", unsafe_allow_html=True)
    tc[2].markdown(f"""
    <div style='background:#1a0f00;border:2px solid #FF8844;border-radius:12px;padding:14px;text-align:center'>
      <div style='color:#FF8844;font-weight:700'>⚡ யமகண்டம்</div>
      <div style='color:#FFB347;font-size:1.1rem;font-weight:600;margin-top:6px'>{pg["yamagandam"]}</div>
      <div style='color:#888;font-size:0.78rem'>Avoid travel · பயணம் வேண்டாம்</div>
    </div>""", unsafe_allow_html=True)

    # ── Daily Do's & Don'ts ─────────────────────────────────────────
    st.markdown("---")
    st.markdown("### ✅ இன்று செய்யலாம் / செய்யக்கூடாது")
    vara_dos = {
        "ஞாயிறு":  (["அரசு அலுவலகம் செல்லலாம்","சூரிய வழிபாடு","தந்தையுடன் நேரம்"],
                     ["புது வியாபாரம் ஆரம்பிக்க வேண்டாம்","வீட்டு மாற்றம் வேண்டாம்"]),
        "திங்கள்":  (["நீர் சார்ந்த காரியங்கள்","தாயுடன் நேரம்","யாத்திரை"],
                     ["கோபமான முடிவுகள் வேண்டாம்","இரவு தாமதம் வேண்டாம்"]),
        "செவ்வாய்": (["நில/சொத்து வாங்கல்","உடற்பயிற்சி","தைரிய காரியங்கள்"],
                     ["திருமண ஏற்பாடு வேண்டாம்","கடன் கொடுக்க வேண்டாம்"]),
        "புதன்":    (["கல்வி, எழுத்து","வியாபார ஒப்பந்தம்","பயணம்"],
                     ["வீண் வாக்குவாதம் வேண்டாம்","புதிய சவால் வேண்டாம்"]),
        "வியாழன்":  (["குரு வழிபாடு","கல்வி ஆரம்பம்","ஆசீர்வாதம் பெறல்"],
                     ["கோர்ட் விஷயம் வேண்டாம்","சண்டை வேண்டாம்"]),
        "வெள்ளி":   (["திருமண ஏற்பாடு","கலை-இசை","அழகு சாதனம்"],
                     ["சட்டவிரோத செயல் வேண்டாம்","எதிரியை எதிர்க்க வேண்டாம்"]),
        "சனி":      (["கடின உழைப்பு","சேவை","பழைய விஷயங்கள் முடிக்கல்"],
                     ["புது தொழில் ஆரம்பம் வேண்டாம்","ஆடம்பரம் வேண்டாம்"]),
    }
    dos, donts = vara_dos.get(pg["vara"], (["பொதுவாக நல்ல நாள்"],["கவனமாக இருங்கள்"]))
    rem_c1, rem_c2 = st.columns(2)
    with rem_c1:
        st.markdown("**✅ செய்யலாம் (Do)**")
        for d in dos:
            st.markdown(f"<div style='background:#0a1500;border-left:3px solid #44FF88;"
                        f"border-radius:6px;padding:8px 12px;margin-bottom:6px;"
                        f"color:#ddd'>✅ {d}</div>", unsafe_allow_html=True)
    with rem_c2:
        st.markdown("**❌ செய்யக்கூடாது (Don't)**")
        for d in donts:
            st.markdown(f"<div style='background:#1f0505;border-left:3px solid #FF4444;"
                        f"border-radius:6px;padding:8px 12px;margin-bottom:6px;"
                        f"color:#ddd'>❌ {d}</div>", unsafe_allow_html=True)

    # ── Upcoming festivals this month ────────────────────────────────
    st.markdown("---")
    st.markdown("### 🎊 இந்த மாதம் திருநாட்கள் — This Month's Festivals")
    month_festivals = []
    for f in TAMIL_FESTIVALS:
        try:
            fdt = datetime(today.year, f["month"], f["day"])
            if fdt.month == today.month:
                days_away = (fdt.date() - today).days
                month_festivals.append({**f, "date": fdt, "days_away": days_away})
        except ValueError:
            pass
    if month_festivals:
        for f in sorted(month_festivals, key=lambda x: x["days_away"]):
            badge_clr = "#44FF88" if f["days_away"] == 0 else (
                "#FFD700" if f["days_away"] <= 3 else "#FFB347")
            st.markdown(f"""
            <div style='background:#1e0a3c;border-left:4px solid {badge_clr};
                 border-radius:8px;padding:10px 14px;margin-bottom:8px'>
              <span style='color:{badge_clr};font-weight:700'>{f["name"]}</span>
              <span style='color:#888;font-size:0.82rem;margin-left:10px'>
                {f["date"].strftime("%d %b")} ·
                {"இன்று!" if f["days_away"]==0 else (f"{f['days_away']} நாளில்")}</span><br>
              <span style='color:#aaa;font-size:0.83rem'>{f["desc"]}</span>
            </div>""", unsafe_allow_html=True)
    else:
        st.info(f"இந்த மாதம் ({today.strftime('%B')}) சிறப்பு திருநாட்கள் இல்லை.")

    # ── Weekly mantra reminder ───────────────────────────────────────
    st.markdown("---")
    st.markdown("### 🙏 இன்றைய ஜப/மந்திர விழிப்பூட்டல்")
    vara_mantra = {
        "ஞாயிறு":  ("ஆதித்ய ஹ்ருதயம் / சூர்ய நமஸ்காரம்",  "☀️", "#FFA500"),
        "திங்கள்":  ("சிவ பஞ்சாக்ஷரம் / சந்திர நமஸ்காரம்","🌙", "#C0C0C0"),
        "செவ்வாய்": ("அங்காரக / ஹனுமான் ஸ்துதி",           "🔴", "#FF4444"),
        "புதன்":    ("விஷ்ணு ஸஹஸ்ர நாமம் / புத ஸ்துதி",   "🟢", "#44FF88"),
        "வியாழன்":  ("குரு ஸ்துதி / விஷ்ணு நாமாவளி",       "💛", "#FFD700"),
        "வெள்ளி":   ("லலிதா ஸஹஸ்ரம் / சுக்ர ஸ்துதி",      "💜", "#FFAAFF"),
        "சனி":      ("சனீஸ்வர ஸ்துதி / ஹனுமான் சாலீஸா",   "🔵", "#8888FF"),
    }
    mantra, m_icon, m_clr = vara_mantra.get(pg["vara"],
        ("ஓம் நமோ நாராயணாய / பொது ஜபம்", "🙏", "#FFB347"))
    st.markdown(f"""
    <div style='background:linear-gradient(135deg,#1e0a3c,#0f0a1e);
         border:2px solid {m_clr};border-radius:12px;padding:16px;text-align:center'>
      <div style='font-size:2rem'>{m_icon}</div>
      <div style='color:{m_clr};font-weight:700;font-size:1.05rem;margin-top:8px'>{pg["vara"]} மந்திரம்</div>
      <div style='color:#ddd;font-size:0.95rem;margin-top:6px'>{mantra}</div>
      <div style='color:#888;font-size:0.8rem;margin-top:6px'>
        108 முறை ஜபிப்பது சிறந்தது · Chant 108 times for best results</div>
    </div>""", unsafe_allow_html=True)


