def _render_global_login():
    """Full-page login/register — shown when no session exists."""
    st.markdown("""
    <div style='text-align:center;padding:20px 0 10px 0;'>
      <h1 style='font-size:2.6rem;margin:0;color:#FF6B35'>🌟 ஜாதகம் Pro</h1>
      <p style='color:#888;font-size:1.0rem;margin:4px 0 0'>Tamil Vedic Astrology · குடும்ப ஜாதக தளம்</p>
    </div>""", unsafe_allow_html=True)

    st.markdown("<br>", unsafe_allow_html=True)
    _, mid, _ = st.columns([1, 2, 1])
    with mid:
        st.markdown("""
        <div style='background:linear-gradient(135deg,#1e0a3c,#2d1040);
             border:2px solid #FF6B35;border-radius:18px;padding:28px 30px'>
        """, unsafe_allow_html=True)

        login_tab, reg_tab = st.tabs(["🔐 உள்நுழைவு / Login", "📝 பதிவு / Register"])

        with login_tab:
            st.markdown("#### 👋 மீண்டும் வரவேற்கிறோம்")
            with st.form("global_login"):
                l_user = st.text_input("பயனர்பெயர் / Username", placeholder="your_username")
                l_pass = st.text_input("கடவுச்சொல் / Password", type="password")
                l_btn  = st.form_submit_button("🔐 உள்நுழை / Login",
                                               use_container_width=True, type="primary")
            if l_btn:
                if not l_user.strip() or not l_pass:
                    st.error("பயனர்பெயர் மற்றும் கடவுச்சொல் தேவை.")
                else:
                    ok, msg = _login(l_user, l_pass)
                    if ok:
                        st.session_state["fp_logged_in"]    = True
                        st.session_state["fp_username"]     = l_user.strip().lower()
                        st.session_state["fp_display_name"] = msg
                        st.rerun()
                    else:
                        st.error(f"❌ {msg}")

        with reg_tab:
            st.markdown("#### 🆕 புதிய கணக்கு")
            with st.form("global_register"):
                r_dname = st.text_input("உங்கள் பெயர் / Display Name", placeholder="e.g. Murugan")
                r_user  = st.text_input("பயனர்பெயர் / Username *", placeholder="letters, numbers (min 3)")
                r_pass  = st.text_input("கடவுச்சொல் / Password *", type="password", placeholder="Min 6 chars")
                r_pass2 = st.text_input("மீண்டும் / Confirm Password", type="password")
                r_btn   = st.form_submit_button("📝 கணக்கு உருவாக்கு",
                                                use_container_width=True, type="primary")
            if r_btn:
                if r_pass != r_pass2:
                    st.error("❌ கடவுச்சொல்கள் பொருந்தவில்லை / Passwords do not match")
                else:
                    ok, msg = _register(r_user, r_pass, r_dname)
                    if ok:
                        st.success(f"✅ {msg}  — இப்போது Login செய்யவும்!")
                    else:
                        st.error(f"❌ {msg}")

        st.markdown("</div>", unsafe_allow_html=True)

    st.markdown("<br>", unsafe_allow_html=True)
    st.info("🔒 உங்கள் குடும்ப ஜாதக தகவல்கள் உள்ளூர் கோப்பில் பாதுகாப்பாக சேமிக்கப்படும்.\n\n"
            "All family data is stored locally in `data/family_data.json` on this server only.")


