def _member_mini_chart(m: dict):
    """Render a compact chart card for a single member inside an expander."""
    try:
        bdt  = datetime.fromisoformat(m["birth_date"] + "T" + m["birth_time"])
        yr, mo, dy, hr, mn = bdt.year, bdt.month, bdt.day, bdt.hour, bdt.minute
        tz   = float(m.get("tz", 5.5))
        lat  = float(m.get("lat", 13.08))
        lon  = float(m.get("lon", 80.27))

        jd, planets, lagna_lon = calc_all_planets(yr, mo, dy, hr, mn, tz, lat, lon)
        lagna_rasi = get_rasi(lagna_lon)
        moon_lon   = planets["சந்திரன்"]
        moon_rasi  = get_rasi(moon_lon)
        moon_nak   = get_nak(moon_lon)
        moon_pada  = get_pada(moon_lon)
        dasha_tl, active_dasha = calc_vimshottari(bdt, moon_lon)
        yogas      = detect_yogas(planets, lagna_rasi)
        today      = datetime.now()

        # ── 4 key metrics ──
        c1, c2, c3, c4 = st.columns(4)
        def mc(col, lbl, val):
            col.markdown(f"""<div class='metric-card'>
              <div class='metric-label'>{lbl}</div>
              <div class='metric-value'>{val}</div></div>""", unsafe_allow_html=True)
        mc(c1, "ஜன்ம ராசி",   f"{RASI[moon_rasi]}")
        mc(c2, "லக்னம்",       f"{RASI[lagna_rasi]}")
        mc(c3, "நட்சத்திரம்",  f"{NAKSHATRA[moon_nak]}")
        mc(c4, "பாதம்",        f"{moon_pada} / 4")

        # ── Dasha bar ──
        st.markdown("---")
        end_y = active_dasha["end"].year
        start_y = active_dasha["start"].year
        elapsed = (today - active_dasha["start"]).days
        total   = (active_dasha["end"] - active_dasha["start"]).days
        pct     = max(0, min(100, int(elapsed / total * 100))) if total else 0
        st.markdown(f"**⏳ நடப்பு தசா:** {active_dasha['planet']} Mahadasha "
                    f"({start_y}–{end_y}) — {pct}% நிறைவு")
        st.progress(pct / 100)

        # ── Planet positions table ──
        st.markdown("**🪐 கிரக நிலைகள்**")
        rows = []
        for p in PLANETS_LIST:
            lon_p = planets.get(p, 0)
            r = get_rasi(lon_p)
            rows.append({
                "கிரகம்": f"{P_SYM.get(p,'')} {p}",
                "ராசி": RASI[r],
                "Rasi": RASI_EN[r],
                "நிலை": planet_status(p, r) if p not in ("ராகு","கேது") else "—",
                "டிகிரி": f"{lon_p % 30:.1f}°",
            })
        st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)

        # ── Top 3 yogas ──
        good_yogas = [y for y in yogas if "⚠️" not in y.get("strength","")][:3]
        if good_yogas:
            st.markdown("**⭐ முக்கிய யோகங்கள்**")
            for y in good_yogas:
                st.markdown(f"• {y['strength']} **{y['name']}** — {y['desc'][:80]}…")

    except Exception as e:
        st.error(f"ஜாதக கணக்கீட்டில் பிழை: {e}")


def _render_family_portal(username: str, display_name: str, members: list):
    """Family member management — Add / Edit / Delete / View charts."""
    st.markdown("""
    <div style='text-align:center;padding:10px 0 4px 0;'>
      <h1 style='font-size:2.2rem;margin:0'>👨‍👩‍👧 குடும்ப நிர்வாகம்</h1>
      <p style='color:#888;margin:0'>Family Member Management · Add · Edit · Delete</p>
    </div>""", unsafe_allow_html=True)
    # Reload members fresh (in case edits happened this run)
    members = _get_members(username)

    # ── Logged-in header ────────────────────────────────────────────
    st.markdown(f"""
    <div style='background:linear-gradient(90deg,#1e0a3c,#0a1f0a,#1e0a3c);
         border:2px solid #44FF88;border-radius:12px;padding:12px 20px;
         margin-bottom:16px;display:flex;justify-content:space-between;align-items:center'>
      <div>
        <div style='color:#44FF88;font-weight:700;font-size:1.1rem'>
          👤 {display_name} குடும்பம்</div>
        <div style='color:#888;font-size:0.82rem'>
          {len(members)} குடும்ப உறுப்பினர்கள் · {len(members)} members stored</div>
      </div>
      <div style='color:#FFB347;font-size:0.88rem'>@{username}</div>
    </div>""", unsafe_allow_html=True)

    # ── Action buttons row ──────────────────────────────────────────
    ab1, ab2, ab3 = st.columns([2, 2, 3])
    add_clicked = ab1.button("➕ புதிய உறுப்பினர்", use_container_width=True, type="primary")
    ab2.button("🔄 புதுப்பி", use_container_width=True, key="fp_refresh",
               on_click=lambda: None)

    # ════════════════════════════════════════════════════════════════
    # ADD MEMBER FORM
    # ════════════════════════════════════════════════════════════════
    if add_clicked:
        st.session_state["fp_show_add"] = True
    if st.session_state.get("fp_show_add"):
        _render_add_member_form(username)

    # ════════════════════════════════════════════════════════════════
    # EDIT MEMBER FORM (if edit requested)
    # ════════════════════════════════════════════════════════════════
    edit_id = st.session_state.get("fp_edit_id")
    if edit_id:
        edit_member = next((m for m in members if m["id"] == edit_id), None)
        if edit_member:
            _render_edit_member_form(username, edit_member)

    # ════════════════════════════════════════════════════════════════
    # MEMBER CARDS
    # ════════════════════════════════════════════════════════════════
    st.markdown("---")
    if not members:
        st.info("👨‍👩‍👧 குடும்ப உறுப்பினர்கள் இல்லை. **➕ புதிய உறுப்பினர்** பொத்தானை அழுத்தி சேர்க்கவும்.")
        return

    st.markdown(f"### 👨‍👩‍👧 குடும்ப உறுப்பினர்கள் ({len(members)})")

    # Relation-based colour
    REL_COLOR = {
        "சொந்தம் / Self": "#FF6B35", "தந்தை / Father": "#FFD700",
        "தாய் / Mother": "#FFAAFF",  "மணாளன் / Husband": "#44FF88",
        "மனைவி / Wife": "#FF88AA",   "மகன் / Son": "#44AAFF",
        "மகள் / Daughter": "#FF88FF","சகோதரன் / Brother": "#88DDFF",
        "சகோதரி / Sister": "#FFBBDD","தாத்தா / Grandfather": "#FFD070",
        "பாட்டி / Grandmother": "#FFB0FF",
    }
    DEF_COLOR = "#FFB347"

    # 2-column card grid
    for i in range(0, len(members), 2):
        cols = st.columns(2)
        for j, col in enumerate(cols):
            if i + j >= len(members):
                break
            m = members[i + j]
            mid = m["id"]
            rel_clr = REL_COLOR.get(m.get("relation", ""), DEF_COLOR)

            with col:
                # Card HTML
                st.markdown(f"""
                <div style='background:linear-gradient(135deg,#1e0a3c,#2d1040);
                     border:2px solid {rel_clr};border-radius:14px;
                     padding:14px 16px;margin-bottom:4px'>
                  <div style='display:flex;justify-content:space-between;align-items:flex-start'>
                    <div>
                      <div style='color:{rel_clr};font-weight:700;font-size:1.05rem'>
                        {m.get("name","—")}</div>
                      <div style='color:#FFB347;font-size:0.82rem;margin-top:2px'>
                        {m.get("relation","")}</div>
                    </div>
                    <div style='color:#888;font-size:0.75rem;text-align:right'>
                      {m.get("birth_date","")}<br>{m.get("birth_time","")}</div>
                  </div>
                  <div style='color:#aaa;font-size:0.8rem;margin-top:8px;
                       display:flex;flex-wrap:wrap;gap:10px'>
                    <span>📍 {m.get("place","")}</span>
                    <span>🕐 UTC+{m.get("tz",5.5)}</span>
                    <span>🌐 {m.get("lat",0):.1f}°N {m.get("lon",0):.1f}°E</span>
                  </div>
                </div>""", unsafe_allow_html=True)

                # Action buttons below each card
                ba1, ba2, ba3 = st.columns(3)
                if ba1.button("📊 ஜாதகம்", key=f"view_{mid}", use_container_width=True):
                    # Toggle view
                    if st.session_state.get("fp_view_id") == mid:
                        st.session_state.pop("fp_view_id", None)
                    else:
                        st.session_state["fp_view_id"]   = mid
                        st.session_state["fp_edit_id"]   = None
                        st.session_state["fp_show_add"]  = False
                if ba2.button("✏️ திருத்து", key=f"edit_{mid}", use_container_width=True):
                    st.session_state["fp_edit_id"]  = mid
                    st.session_state["fp_view_id"]  = None
                    st.session_state["fp_show_add"] = False
                    st.rerun()
                if ba3.button("🗑️ நீக்கு", key=f"del_{mid}", use_container_width=True):
                    st.session_state["fp_confirm_del"] = mid
                    st.rerun()

                # Delete confirmation
                if st.session_state.get("fp_confirm_del") == mid:
                    st.warning(f"⚠️ **{m.get('name','')}** — உறுப்பினரை நீக்கவா?")
                    dc1, dc2 = st.columns(2)
                    if dc1.button("✅ ஆம், நீக்கு", key=f"conf_{mid}", use_container_width=True):
                        _remove_member(username, mid)
                        st.session_state.pop("fp_confirm_del", None)
                        st.success(f"'{m.get('name','')}' நீக்கப்பட்டது.")
                        st.rerun()
                    if dc2.button("❌ வேண்டாம்", key=f"canc_{mid}", use_container_width=True):
                        st.session_state.pop("fp_confirm_del", None)
                        st.rerun()

                # Mini-chart expander
                if st.session_state.get("fp_view_id") == mid:
                    with st.expander(f"📊 {m.get('name','')} ஜாதகம்", expanded=True):
                        _member_mini_chart(m)


def _render_add_member_form(username: str):
    """Add-new-member form inside a styled card."""
    st.markdown("""
    <div style='background:#0a1f0a;border:2px solid #44FF88;
         border-radius:14px;padding:16px;margin-bottom:12px'>
      <div style='color:#44FF88;font-weight:700;font-size:1.05rem;margin-bottom:12px'>
        ➕ புதிய உறுப்பினர் சேர்க்கவும் — Add New Member</div>
    </div>""", unsafe_allow_html=True)

    with st.form("add_member_form", clear_on_submit=True):
        fc1, fc2 = st.columns(2)
        m_name     = fc1.text_input("பெயர் / Name *", placeholder="உறுப்பினர் பெயர்")
        m_relation = fc2.selectbox("உறவு / Relation *", RELATION_OPTIONS)
        fd1, fd2   = st.columns(2)
        m_bdate    = fd1.date_input("பிறந்த தேதி *", value=date(1990,1,1),
                                     min_value=date(1900,1,1), max_value=date.today())
        m_btime    = fd2.time_input("பிறந்த நேரம் *",
                                     value=datetime(2000,1,1,6,0).time())
        fp1, fp2   = st.columns(2)
        m_place    = fp1.text_input("பிறந்த இடம்", placeholder="Chennai")
        m_tz       = fp2.slider("Time Zone (UTC+)", -12.0, 14.0, 5.5, 0.5)
        fl1, fl2   = st.columns(2)
        m_lat      = fl1.number_input("Latitude °N", -90.0, 90.0, 13.08, 0.01, format="%.4f")
        m_lon      = fl2.number_input("Longitude °E",-180.0,180.0, 80.27, 0.01, format="%.4f")
        m_notes    = st.text_area("குறிப்புகள் / Notes", placeholder="Optional notes…", height=80)

        fs1, fs2, _ = st.columns([1, 1, 2])
        with fs1:
            submitted = st.form_submit_button("✅ சேர்க்கவும்", use_container_width=True, type="primary")
        with fs2:
            cancelled = st.form_submit_button("❌ ரத்து", use_container_width=True)

    if submitted:
        if not m_name.strip():
            st.error("பெயர் கட்டாயம் தேவை / Name is required")
        else:
            _add_member(username, {
                "name":       m_name.strip(),
                "relation":   m_relation,
                "birth_date": m_bdate.isoformat(),
                "birth_time": m_btime.strftime("%H:%M"),
                "place":      m_place.strip(),
                "tz":         m_tz,
                "lat":        m_lat,
                "lon":        m_lon,
                "notes":      m_notes.strip(),
            })
            st.success(f"✅ '{m_name.strip()}' சேர்க்கப்பட்டது!")
            st.session_state["fp_show_add"] = False
            st.rerun()
    if cancelled:
        st.session_state["fp_show_add"] = False
        st.rerun()


def _render_edit_member_form(username: str, m: dict):
    """Edit existing member form."""
    st.markdown(f"""
    <div style='background:#1a1000;border:2px solid #FFB347;
         border-radius:14px;padding:14px;margin-bottom:12px'>
      <div style='color:#FFB347;font-weight:700;font-size:1.0rem'>
        ✏️ திருத்தவும்: {m.get("name","")} — Edit Member</div>
    </div>""", unsafe_allow_html=True)

    try:
        def_date = date.fromisoformat(m["birth_date"])
        h, mn    = map(int, m.get("birth_time","06:00").split(":"))
        def_time = datetime(2000,1,1,h,mn).time()
    except Exception:
        def_date = date(1990,1,1)
        def_time = datetime(2000,1,1,6,0).time()

    with st.form("edit_member_form"):
        ec1, ec2 = st.columns(2)
        e_name     = ec1.text_input("பெயர் / Name",    value=m.get("name",""))
        e_relation = ec2.selectbox("உறவு / Relation",  RELATION_OPTIONS,
                                    index=RELATION_OPTIONS.index(m.get("relation", RELATION_OPTIONS[0]))
                                    if m.get("relation") in RELATION_OPTIONS else 0)
        ed1, ed2   = st.columns(2)
        e_bdate    = ed1.date_input("பிறந்த தேதி", value=def_date,
                                     min_value=date(1900,1,1), max_value=date.today())
        e_btime    = ed2.time_input("பிறந்த நேரம்", value=def_time)
        ep1, ep2   = st.columns(2)
        e_place    = ep1.text_input("பிறந்த இடம்", value=m.get("place",""))
        e_tz       = ep2.slider("Time Zone", -12.0, 14.0, float(m.get("tz",5.5)), 0.5)
        el1, el2   = st.columns(2)
        e_lat      = el1.number_input("Latitude",  -90.0, 90.0,  float(m.get("lat",13.08)), 0.01, format="%.4f")
        e_lon      = el2.number_input("Longitude", -180.0,180.0, float(m.get("lon",80.27)), 0.01, format="%.4f")
        e_notes    = st.text_area("குறிப்புகள்", value=m.get("notes",""), height=80)

        es1, es2 = st.columns(2)
        with es1:
            saved    = st.form_submit_button("💾 சேமி", use_container_width=True, type="primary")
        with es2:
            cancel_e = st.form_submit_button("❌ ரத்து", use_container_width=True)

    if saved:
        _update_member(username, m["id"], {
            "name":       e_name.strip(),
            "relation":   e_relation,
            "birth_date": e_bdate.isoformat(),
            "birth_time": e_btime.strftime("%H:%M"),
            "place":      e_place.strip(),
            "tz":         e_tz,
            "lat":        e_lat,
            "lon":        e_lon,
            "notes":      e_notes.strip(),
        })
        st.success("✅ மாற்றங்கள் சேமிக்கப்பட்டது!")
        st.session_state.pop("fp_edit_id", None)
        st.rerun()
    if cancel_e:
        st.session_state.pop("fp_edit_id", None)
        st.rerun()


# _render_auth_screen() removed — replaced by _render_global_login()


# ═══════════════════════════════════════════════════════════════════
if __name__ == "__main__":
    main()
